insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ001','Làm thế nào để đăng ký POLYMATCH?','Nhóm: Tài khoản
Câu hỏi chuẩn: Làm thế nào để đăng ký POLYMATCH?
Cách hỏi tương đương: Tạo tài khoản thế nào?; Đăng ký doanh nghiệp ở đâu?
Câu trả lời chuẩn: Theo quy trình dự kiến, doanh nghiệp chọn vai trò phù hợp (doanh nghiệp có nhu cầu hoặc nhà cung cấp), điền thông tin đăng ký và xác thực theo hướng dẫn trên nền tảng. Quy trình, trường thông tin bắt buộc và trạng thái mở đăng ký cần được nhóm POLYMATCH xác nhận trước khi chatbot trả lời như thông tin chính thức.
Từ khóa: đăng ký; tài khoản; doanh nghiệp
Ngoại lệ: Không tự khẳng định website đang mở đăng ký hoặc thời gian duyệt nếu chưa được cấu hình/xác nhận.
Nguồn: Thông tin nội bộ POLYMATCH – cần nhóm sản phẩm xác nhận
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','FAQ_CSKH',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "FAQ_CSKH", "row": 4}, "fields": {"ID": "FAQ001", "Nhóm": "Tài khoản", "Câu hỏi chuẩn": "Làm thế nào để đăng ký POLYMATCH?", "Cách hỏi tương đương": "Tạo tài khoản thế nào?; Đăng ký doanh nghiệp ở đâu?", "Câu trả lời chuẩn": "Theo quy trình dự kiến, doanh nghiệp chọn vai trò phù hợp (doanh nghiệp có nhu cầu hoặc nhà cung cấp), điền thông tin đăng ký và xác thực theo hướng dẫn trên nền tảng. Quy trình, trường thông tin bắt buộc và trạng thái mở đăng ký cần được nhóm POLYMATCH xác nhận trước khi chatbot trả lời như thông tin chính thức.", "Từ khóa": "đăng ký; tài khoản; doanh nghiệp", "Ngoại lệ": "Không tự khẳng định website đang mở đăng ký hoặc thời gian duyệt nếu chưa được cấu hình/xác nhận.", "Nguồn": "Thông tin nội bộ POLYMATCH – cần nhóm sản phẩm xác nhận", "Người duyệt": "Nhóm POLYMATCH", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ002','POLYMATCH phục vụ những đối tượng nào?','Nhóm: Vai trò người dùng
Câu hỏi chuẩn: POLYMATCH phục vụ những đối tượng nào?
Cách hỏi tương đương: Ai có thể dùng POLYMATCH?; Bên mua và bên bán là ai?
Câu trả lời chuẩn: Định hướng sản phẩm là kết nối hai nhóm: (1) doanh nghiệp logistics/chuỗi cung ứng có nhu cầu đánh giá hiện trạng và tìm giải pháp số; (2) nhà cung cấp phần mềm, thiết bị, giải pháp và dịch vụ tư vấn liên quan. Quyền truy cập và điều kiện tham gia từng nhóm cần theo chính sách đang áp dụng.
Từ khóa: doanh nghiệp; bên mua; nhà cung cấp; người dùng
Ngoại lệ: Không suy diễn rằng mọi cá nhân hoặc nhà cung cấp đều được duyệt tự động.
Nguồn: Thông tin mô tả dự án POLYMATCH – cần nhóm dự án xác nhận
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','FAQ_CSKH',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "FAQ_CSKH", "row": 5}, "fields": {"ID": "FAQ002", "Nhóm": "Vai trò người dùng", "Câu hỏi chuẩn": "POLYMATCH phục vụ những đối tượng nào?", "Cách hỏi tương đương": "Ai có thể dùng POLYMATCH?; Bên mua và bên bán là ai?", "Câu trả lời chuẩn": "Định hướng sản phẩm là kết nối hai nhóm: (1) doanh nghiệp logistics/chuỗi cung ứng có nhu cầu đánh giá hiện trạng và tìm giải pháp số; (2) nhà cung cấp phần mềm, thiết bị, giải pháp và dịch vụ tư vấn liên quan. Quyền truy cập và điều kiện tham gia từng nhóm cần theo chính sách đang áp dụng.", "Từ khóa": "doanh nghiệp; bên mua; nhà cung cấp; người dùng", "Ngoại lệ": "Không suy diễn rằng mọi cá nhân hoặc nhà cung cấp đều được duyệt tự động.", "Nguồn": "Thông tin mô tả dự án POLYMATCH – cần nhóm dự án xác nhận", "Người duyệt": "Nhóm POLYMATCH", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ003','Đánh giá mức độ chuyển đổi số trên POLYMATCH có ý nghĩa gì?','Nhóm: Đánh giá DBI
Câu hỏi chuẩn: Đánh giá mức độ chuyển đổi số trên POLYMATCH có ý nghĩa gì?
Cách hỏi tương đương: DBI là gì?; Tại sao phải đánh giá?
Câu trả lời chuẩn: Đánh giá giúp doanh nghiệp tự rà soát mức độ ứng dụng công nghệ, quy trình, dữ liệu và năng lực quản trị; kết quả là cơ sở nhận diện khoảng trống và xác định ưu tiên cải thiện. Kết quả tự đánh giá không mặc nhiên là chứng nhận, kiểm toán hay kết luận độc lập về năng lực doanh nghiệp.
Từ khóa: DBI; đánh giá; chuyển đổi số; mức độ trưởng thành
Ngoại lệ: Nêu rõ bộ tiêu chí, phiên bản và phương pháp chấm điểm đang được POLYMATCH sử dụng; không gọi kết quả là chứng nhận chính thức nếu không có thẩm quyền.
Nguồn: Khung đánh giá và tài liệu nội bộ POLYMATCH; đối chiếu Quyết định 1567/QĐ-BKHCN nếu dự án sử dụng bộ chỉ số này
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','FAQ_CSKH',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "FAQ_CSKH", "row": 6}, "fields": {"ID": "FAQ003", "Nhóm": "Đánh giá DBI", "Câu hỏi chuẩn": "Đánh giá mức độ chuyển đổi số trên POLYMATCH có ý nghĩa gì?", "Cách hỏi tương đương": "DBI là gì?; Tại sao phải đánh giá?", "Câu trả lời chuẩn": "Đánh giá giúp doanh nghiệp tự rà soát mức độ ứng dụng công nghệ, quy trình, dữ liệu và năng lực quản trị; kết quả là cơ sở nhận diện khoảng trống và xác định ưu tiên cải thiện. Kết quả tự đánh giá không mặc nhiên là chứng nhận, kiểm toán hay kết luận độc lập về năng lực doanh nghiệp.", "Từ khóa": "DBI; đánh giá; chuyển đổi số; mức độ trưởng thành", "Ngoại lệ": "Nêu rõ bộ tiêu chí, phiên bản và phương pháp chấm điểm đang được POLYMATCH sử dụng; không gọi kết quả là chứng nhận chính thức nếu không có thẩm quyền.", "Nguồn": "Khung đánh giá và tài liệu nội bộ POLYMATCH; đối chiếu Quyết định 1567/QĐ-BKHCN nếu dự án sử dụng bộ chỉ số này", "Người duyệt": "Nhóm chuyên môn POLYMATCH", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ004','Tôi nhận được kết quả đánh giá thấp, nên làm gì?','Nhóm: Kết quả đánh giá
Câu hỏi chuẩn: Tôi nhận được kết quả đánh giá thấp, nên làm gì?
Cách hỏi tương đương: Điểm chuyển đổi số thấp thì sao?; Làm thế nào cải thiện?
Câu trả lời chuẩn: Không nên mua công nghệ ngay chỉ dựa trên điểm tổng. Hãy xem từng nhóm tiêu chí, xác định quy trình gây tổn thất lớn, mức độ sẵn sàng của nhân sự, chất lượng dữ liệu, ngân sách và khả năng tích hợp. Sau đó chọn một bài toán ưu tiên, đặt KPI nền và thử nghiệm quy mô nhỏ trước khi mở rộng.
Từ khóa: điểm thấp; kết quả; cải thiện; lộ trình
Ngoại lệ: Không đưa ra kết luận chuyên sâu nếu thiếu dữ liệu vận hành; khuyến nghị doanh nghiệp trao đổi chuyên gia khi cần.
Nguồn: ASCM SCOR Performance; OECD Digitalisation of SMEs: https://www.oecd.org/en/topics/digitalisation-of-smes.html
Ngày cập nhật: 2026-11-11T00:00:00','knowledge','Cần duyệt','FAQ_CSKH',false,'https://www.oecd.org/en/topics/digitalisation-of-smes.html','["https://www.oecd.org/en/topics/digitalisation-of-smes.html"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "FAQ_CSKH", "row": 7}, "fields": {"ID": "FAQ004", "Nhóm": "Kết quả đánh giá", "Câu hỏi chuẩn": "Tôi nhận được kết quả đánh giá thấp, nên làm gì?", "Cách hỏi tương đương": "Điểm chuyển đổi số thấp thì sao?; Làm thế nào cải thiện?", "Câu trả lời chuẩn": "Không nên mua công nghệ ngay chỉ dựa trên điểm tổng. Hãy xem từng nhóm tiêu chí, xác định quy trình gây tổn thất lớn, mức độ sẵn sàng của nhân sự, chất lượng dữ liệu, ngân sách và khả năng tích hợp. Sau đó chọn một bài toán ưu tiên, đặt KPI nền và thử nghiệm quy mô nhỏ trước khi mở rộng.", "Từ khóa": "điểm thấp; kết quả; cải thiện; lộ trình", "Ngoại lệ": "Không đưa ra kết luận chuyên sâu nếu thiếu dữ liệu vận hành; khuyến nghị doanh nghiệp trao đổi chuyên gia khi cần.", "Nguồn": "ASCM SCOR Performance; OECD Digitalisation of SMEs: https://www.oecd.org/en/topics/digitalisation-of-smes.html", "Người duyệt": "Chatbot POLYMATCH – câu trả lời định hướng, cần chuyên gia duyệt", "Ngày cập nhật": "2026-11-11T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ005','POLYMATCH có đảm bảo giải pháp được đề xuất phù hợp 100% không?','Nhóm: Tư vấn công nghệ
Câu hỏi chuẩn: POLYMATCH có đảm bảo giải pháp được đề xuất phù hợp 100% không?
Cách hỏi tương đương: Giải pháp có chắc chắn phù hợp?; Có cam kết hiệu quả không?
Câu trả lời chuẩn: Không nên cam kết phù hợp tuyệt đối hoặc bảo đảm ROI khi chưa khảo sát đầy đủ. Mức độ phù hợp phụ thuộc vào quy trình, quy mô, hệ thống hiện có, dữ liệu, ngân sách, nhân sự và điều khoản của nhà cung cấp. Doanh nghiệp cần xác minh yêu cầu, thử nghiệm (POC/pilot) và thống nhất tiêu chí nghiệm thu.
Từ khóa: phù hợp; cam kết; ROI; hiệu quả; POC
Ngoại lệ: Không cam kết tiết kiệm chi phí, tăng năng suất hoặc thời gian hoàn vốn khi chưa có dữ liệu và hợp đồng cụ thể.
Nguồn: NIST AI RMF (nguyên tắc độ tin cậy); OECD SME digitalisation
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','FAQ_CSKH',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "FAQ_CSKH", "row": 8}, "fields": {"ID": "FAQ005", "Nhóm": "Tư vấn công nghệ", "Câu hỏi chuẩn": "POLYMATCH có đảm bảo giải pháp được đề xuất phù hợp 100% không?", "Cách hỏi tương đương": "Giải pháp có chắc chắn phù hợp?; Có cam kết hiệu quả không?", "Câu trả lời chuẩn": "Không nên cam kết phù hợp tuyệt đối hoặc bảo đảm ROI khi chưa khảo sát đầy đủ. Mức độ phù hợp phụ thuộc vào quy trình, quy mô, hệ thống hiện có, dữ liệu, ngân sách, nhân sự và điều khoản của nhà cung cấp. Doanh nghiệp cần xác minh yêu cầu, thử nghiệm (POC/pilot) và thống nhất tiêu chí nghiệm thu.", "Từ khóa": "phù hợp; cam kết; ROI; hiệu quả; POC", "Ngoại lệ": "Không cam kết tiết kiệm chi phí, tăng năng suất hoặc thời gian hoàn vốn khi chưa có dữ liệu và hợp đồng cụ thể.", "Nguồn": "NIST AI RMF (nguyên tắc độ tin cậy); OECD SME digitalisation", "Người duyệt": "Nhóm tư vấn POLYMATCH", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ006','Nhà cung cấp cần cung cấp thông tin gì?','Nhóm: Nhà cung cấp
Câu hỏi chuẩn: Nhà cung cấp cần cung cấp thông tin gì?
Cách hỏi tương đương: Đăng ký làm đối tác cần gì?
Câu trả lời chuẩn: Thông tin nên thu thập gồm pháp nhân và mã số thuế, lĩnh vực cung cấp, mô tả sản phẩm/dịch vụ, nhóm khách hàng phù hợp, tính năng và giới hạn, phương án triển khai/tích hợp, bảo mật dữ liệu, hỗ trợ sau bán, tài liệu tham chiếu và đầu mối liên hệ. Danh mục bắt buộc và quy trình xác minh phải theo chính sách POLYMATCH đã ban hành.
Từ khóa: nhà cung cấp; hồ sơ; mã số thuế; đối tác
Ngoại lệ: Không tuyên bố đã xác minh pháp nhân/chất lượng nếu chưa thực hiện bước kiểm tra và lưu bằng chứng.
Nguồn: Thông tin nội bộ POLYMATCH – cần nhóm dự án xác nhận
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','FAQ_CSKH',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "FAQ_CSKH", "row": 9}, "fields": {"ID": "FAQ006", "Nhóm": "Nhà cung cấp", "Câu hỏi chuẩn": "Nhà cung cấp cần cung cấp thông tin gì?", "Cách hỏi tương đương": "Đăng ký làm đối tác cần gì?", "Câu trả lời chuẩn": "Thông tin nên thu thập gồm pháp nhân và mã số thuế, lĩnh vực cung cấp, mô tả sản phẩm/dịch vụ, nhóm khách hàng phù hợp, tính năng và giới hạn, phương án triển khai/tích hợp, bảo mật dữ liệu, hỗ trợ sau bán, tài liệu tham chiếu và đầu mối liên hệ. Danh mục bắt buộc và quy trình xác minh phải theo chính sách POLYMATCH đã ban hành.", "Từ khóa": "nhà cung cấp; hồ sơ; mã số thuế; đối tác", "Ngoại lệ": "Không tuyên bố đã xác minh pháp nhân/chất lượng nếu chưa thực hiện bước kiểm tra và lưu bằng chứng.", "Nguồn": "Thông tin nội bộ POLYMATCH – cần nhóm dự án xác nhận", "Người duyệt": "Nhóm vận hành POLYMATCH", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ007','Doanh nghiệp có nên nhập dữ liệu nhạy cảm vào chatbot không?','Nhóm: Bảo mật dữ liệu
Câu hỏi chuẩn: Doanh nghiệp có nên nhập dữ liệu nhạy cảm vào chatbot không?
Cách hỏi tương đương: Dữ liệu của tôi có an toàn không?; Có nên gửi hợp đồng/báo giá?
Câu trả lời chuẩn: Chỉ cung cấp thông tin cần thiết cho mục đích tư vấn. Không nhập mật khẩu, dữ liệu cá nhân nhạy cảm, thông tin tài khoản, bí mật kinh doanh, hợp đồng hoặc báo giá mật nếu chưa có cơ chế bảo vệ và căn cứ chia sẻ phù hợp. Chính sách lưu trữ, xử lý, chia sẻ và xóa dữ liệu phải được POLYMATCH công bố rõ.
Từ khóa: bảo mật; dữ liệu; riêng tư; hợp đồng
Ngoại lệ: Chatbot không được tự cam kết dữ liệu không lưu trữ hoặc không chia sẻ nếu chưa có chính sách kỹ thuật/pháp lý được phê duyệt.
Nguồn: NIST AI RMF: https://www.nist.gov/itl/ai-risk-management-framework/ai-risk-management-framework-faqs
