insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ009','POLYMATCH là nền tảng gì?','Nhóm: Tài khoản
Câu hỏi chuẩn: POLYMATCH là nền tảng gì?
Cách hỏi tương đương: POLYMATCH hoạt động như thế nào?; POLYMATCH dùng để làm gì?; Nền tảng này hỗ trợ những gì?
