insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ012','POLYMATCH có những loại tài khoản nào?','Nhóm: Tài khoản
Câu hỏi chuẩn: POLYMATCH có những loại tài khoản nào?
Cách hỏi tương đương: Có mấy loại tài khoản?; Tôi nên chọn tài khoản nào?; Tài khoản bên mua và bên bán khác nhau thế nào?
Câu trả lời chuẩn: POLYMATCH định hướng phục vụ hai nhóm tài khoản chính: bên mua là doanh nghiệp có nhu cầu chuyển đổi số và bên bán là nhà cung cấp giải pháp công nghệ. Ngoài ra, hệ thống có vai trò quản trị để quản lý hoạt động nền tảng.
