insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ013','Tôi có thể đăng ký tài khoản với tư cách cá nhân không?','Nhóm: Tài khoản
Câu hỏi chuẩn: Tôi có thể đăng ký tài khoản với tư cách cá nhân không?
Cách hỏi tương đương: Cá nhân có dùng được không?; Sinh viên có thể đăng ký không?; Không đại diện doanh nghiệp có tham gia được không?
Câu trả lời chuẩn: POLYMATCH chủ yếu phục vụ doanh nghiệp và nhà cung cấp giải pháp công nghệ. Nếu bạn là cá nhân muốn tìm hiểu hoặc hợp tác, vui lòng liên hệ bộ phận hỗ trợ để được hướng dẫn.
Từ khóa: cá nhân, đăng ký, sinh viên, tài khoản
Ngoại lệ: Không tự xác nhận quyền đăng ký của cá nhân khi chưa có chính sách chính thức.
Nguồn: Định hướng đối tượng khách hàng POLYMATCH
