insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ014','Tôi quên mật khẩu tài khoản thì phải làm gì?','Nhóm: Tài khoản
Câu hỏi chuẩn: Tôi quên mật khẩu tài khoản thì phải làm gì?
Cách hỏi tương đương: Không đăng nhập được do quên mật khẩu; Cách lấy lại mật khẩu?; Làm sao đặt lại mật khẩu?
Câu trả lời chuẩn: Bạn hãy sử dụng chức năng quên mật khẩu trên màn hình đăng nhập nếu hệ thống hỗ trợ. Nếu không thể khôi phục tài khoản, hãy liên hệ bộ phận hỗ trợ POLYMATCH để được kiểm tra.
Từ khóa: quên mật khẩu, khôi phục, đăng nhập
Ngoại lệ: Không yêu cầu người dùng cung cấp mật khẩu hoặc mã OTP cho chatbot.
