insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ031','Doanh nghiệp đã sử dụng ERP có thể triển khai thêm WMS hoặc TMS không?','Nhóm: Tương thích công nghệ
Câu hỏi chuẩn: Doanh nghiệp đã sử dụng ERP có thể triển khai thêm WMS hoặc TMS không?
Cách hỏi tương đương: Có ERP rồi có dùng WMS được không?; ERP có kết nối TMS không?; Các phần mềm có chạy cùng nhau được không?
Câu trả lời chuẩn: Có thể, nhưng cần kiểm tra khả năng kết nối giữa các hệ thống, phương thức trao đổi dữ liệu, API, định dạng dữ liệu và chi phí tích hợp trước khi triển khai.
Từ khóa: ERP, WMS, TMS, tích hợp, tương thích
Ngoại lệ: Không khẳng định hai hệ thống tương thích nếu chưa có tài liệu kỹ thuật hoặc kiểm thử.
Nguồn: Tài liệu kỹ thuật hệ thống và định hướng Technology Compatibility Checker
