insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ033','Doanh nghiệp chưa có đội ngũ IT có thể chuyển đổi số không?','Nhóm: Sẵn sàng công nghệ
Câu hỏi chuẩn: Doanh nghiệp chưa có đội ngũ IT có thể chuyển đổi số không?
Cách hỏi tương đương: Không có nhân viên IT thì có dùng phần mềm được không?; Công ty nhỏ không có IT thì làm sao?
Câu trả lời chuẩn: Có thể. Doanh nghiệp nên bắt đầu với các giải pháp dễ sử dụng, có hỗ trợ kỹ thuật và tài liệu hướng dẫn rõ ràng. Đồng thời, cần đào tạo nhân viên hoặc tìm kiếm đơn vị tư vấn phù hợp để hỗ trợ triển khai.
Từ khóa: nhân sự IT, thiếu nhân lực, đào tạo, chuyển đổi số
Ngoại lệ: Không khuyến nghị triển khai hệ thống phức tạp nếu thiếu nguồn lực vận hành và hỗ trợ.
Nguồn: Định hướng tư vấn POLYMATCH
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','FAQ_CSKH',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "FAQ_CSKH", "row": 36}, "fields": {"ID": "FAQ033", "Nhóm": "Sẵn sàng công nghệ", "Câu hỏi chuẩn": "Doanh nghiệp chưa có đội ngũ IT có thể chuyển đổi số không?", "Cách hỏi tương đương": "Không có nhân viên IT thì có dùng phần mềm được không?; Công ty nhỏ không có IT thì làm sao?", "Câu trả lời chuẩn": "Có thể. Doanh nghiệp nên bắt đầu với các giải pháp dễ sử dụng, có hỗ trợ kỹ thuật và tài liệu hướng dẫn rõ ràng. Đồng thời, cần đào tạo nhân viên hoặc tìm kiếm đơn vị tư vấn phù hợp để hỗ trợ triển khai.", "Từ khóa": "nhân sự IT, thiếu nhân lực, đào tạo, chuyển đổi số", "Ngoại lệ": "Không khuyến nghị triển khai hệ thống phức tạp nếu thiếu nguồn lực vận hành và hỗ trợ.", "Nguồn": "Định hướng tư vấn POLYMATCH", "Người duyệt": "Nhóm POLYMATCH", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ034','Nhân viên không muốn sử dụng công nghệ mới thì doanh nghiệp nên làm gì?','Nhóm: Sẵn sàng công nghệ
Câu hỏi chuẩn: Nhân viên không muốn sử dụng công nghệ mới thì doanh nghiệp nên làm gì?
Cách hỏi tương đương: Nhân viên phản đối chuyển đổi số; Làm sao để nhân viên chịu dùng phần mềm?; Kháng cự thay đổi xử lý thế nào?
Câu trả lời chuẩn: Doanh nghiệp nên đánh giá nguyên nhân của sự phản đối, tổ chức đào tạo, giải thích lợi ích của công nghệ và cho nhân viên tham gia vào quá trình thay đổi. Nên bắt đầu thử nghiệm ở một bộ phận nhỏ trước khi triển khai rộng rãi.
Từ khóa: nhân viên, kháng cự thay đổi, đào tạo, văn hóa số
Ngoại lệ: Nếu nguyên nhân liên quan đến tranh chấp lao động hoặc vấn đề nhân sự nghiêm trọng, cần chuyển chuyên viên phù hợp.
Nguồn: Định hướng đánh giá mức độ sẵn sàng chuyển đổi số POLYMATCH
