insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ037','Nhà cung cấp cần cung cấp những thông tin gì khi đăng ký?','Nhóm: Nhà cung cấp
Câu hỏi chuẩn: Nhà cung cấp cần cung cấp những thông tin gì khi đăng ký?
Cách hỏi tương đương: Hồ sơ nhà cung cấp gồm những gì?; Cần giấy tờ gì để tham gia?; Đăng ký sản phẩm cần thông tin nào?
Câu trả lời chuẩn: Nhà cung cấp nên chuẩn bị thông tin doanh nghiệp, mã số thuế, lĩnh vực hoạt động, sản phẩm hoặc dịch vụ cung cấp, tính năng, nhóm khách hàng mục tiêu, thông tin liên hệ và tài liệu chứng minh năng lực nếu có.
Từ khóa: hồ sơ, mã số thuế, sản phẩm, dịch vụ, nhà cung cấp
Ngoại lệ: Không yêu cầu tài liệu pháp lý ngoài danh mục được POLYMATCH công bố.
Nguồn: Quy trình đăng ký nhà cung cấp POLYMATCH
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','FAQ_CSKH',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "FAQ_CSKH", "row": 40}, "fields": {"ID": "FAQ037", "Nhóm": "Nhà cung cấp", "Câu hỏi chuẩn": "Nhà cung cấp cần cung cấp những thông tin gì khi đăng ký?", "Cách hỏi tương đương": "Hồ sơ nhà cung cấp gồm những gì?; Cần giấy tờ gì để tham gia?; Đăng ký sản phẩm cần thông tin nào?", "Câu trả lời chuẩn": "Nhà cung cấp nên chuẩn bị thông tin doanh nghiệp, mã số thuế, lĩnh vực hoạt động, sản phẩm hoặc dịch vụ cung cấp, tính năng, nhóm khách hàng mục tiêu, thông tin liên hệ và tài liệu chứng minh năng lực nếu có.", "Từ khóa": "hồ sơ, mã số thuế, sản phẩm, dịch vụ, nhà cung cấp", "Ngoại lệ": "Không yêu cầu tài liệu pháp lý ngoài danh mục được POLYMATCH công bố.", "Nguồn": "Quy trình đăng ký nhà cung cấp POLYMATCH", "Người duyệt": "Nhóm POLYMATCH", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ038','Vì sao nhà cung cấp cần xác minh mã số thuế?','Nhóm: Nhà cung cấp
Câu hỏi chuẩn: Vì sao nhà cung cấp cần xác minh mã số thuế?
Cách hỏi tương đương: Tại sao phải nhập mã số thuế?; POLYMATCH kiểm tra mã số thuế để làm gì?; Xác minh doanh nghiệp có tác dụng gì?
Câu trả lời chuẩn: Việc xác minh mã số thuế giúp hỗ trợ nhận diện và kiểm tra thông tin pháp lý cơ bản của doanh nghiệp, góp phần nâng cao độ tin cậy và minh bạch khi kết nối giữa các bên.
Từ khóa: mã số thuế, xác minh, pháp lý, doanh nghiệp
Ngoại lệ: Không coi việc xác minh mã số thuế là bảo đảm tuyệt đối về chất lượng dịch vụ hoặc uy tín nhà cung cấp.
Nguồn: Quy trình xác minh nhà cung cấp POLYMATCH cần xác nhận
