insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ039','Đăng ký nhà cung cấp có đồng nghĩa với việc được duyệt ngay không?','Nhóm: Nhà cung cấp
Câu hỏi chuẩn: Đăng ký nhà cung cấp có đồng nghĩa với việc được duyệt ngay không?
Cách hỏi tương đương: Đăng ký xong có được hoạt động luôn không?; Bao lâu thì được duyệt?; Tại sao tài khoản chưa được phê duyệt?
Câu trả lời chuẩn: Không. Thông tin đăng ký cần được xem xét và xác minh theo quy trình của nền tảng. Việc cung cấp đầy đủ, chính xác thông tin sẽ hỗ trợ quá trình kiểm duyệt.
Từ khóa: phê duyệt, kiểm duyệt, xác minh, thời gian
Ngoại lệ: Không tự cam kết thời gian phê duyệt nếu chưa có SLA chính thức.
Nguồn: Quy trình kiểm duyệt nhà cung cấp POLYMATCH
