insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ040','Nhà cung cấp có được chỉnh sửa thông tin sản phẩm sau khi đăng ký không?','Nhóm: Nhà cung cấp
Câu hỏi chuẩn: Nhà cung cấp có được chỉnh sửa thông tin sản phẩm sau khi đăng ký không?
Cách hỏi tương đương: Sửa thông tin phần mềm thế nào?; Cập nhật sản phẩm được không?; Thay đổi giá và tính năng ở đâu?
Câu trả lời chuẩn: Nhà cung cấp nên cập nhật thông tin khi có thay đổi về tính năng, giá, chính sách hoặc phạm vi cung cấp dịch vụ. Khả năng tự chỉnh sửa phụ thuộc vào quyền tài khoản và chức năng hiện có của nền tảng.
Từ khóa: chỉnh sửa sản phẩm, cập nhật, giá, tính năng
Ngoại lệ: Không hướng dẫn thao tác chưa có trên giao diện thực tế.
Nguồn: Chức năng quản lý nhà cung cấp POLYMATCH cần xác nhận
