insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ044','Nếu nhà cung cấp không thực hiện đúng cam kết thì doanh nghiệp phải làm gì?','Nhóm: Kết nối
Câu hỏi chuẩn: Nếu nhà cung cấp không thực hiện đúng cam kết thì doanh nghiệp phải làm gì?
Cách hỏi tương đương: Nhà cung cấp không làm đúng hợp đồng thì sao?; Muốn khiếu nại đối tác; Đối tác giao phần mềm chậm thì xử lý thế nào?
Câu trả lời chuẩn: Doanh nghiệp nên lưu giữ hợp đồng, báo giá, biên bản nghiệm thu và các trao đổi liên quan. Bạn có thể gửi phản ánh tới bộ phận hỗ trợ POLYMATCH để được tiếp nhận thông tin và hướng dẫn theo phạm vi hỗ trợ của nền tảng.
Từ khóa: khiếu nại, vi phạm cam kết, nhà cung cấp, hợp đồng
Ngoại lệ: Không kết luận lỗi thuộc về bên nào hoặc cam kết bồi thường thay các bên.
Nguồn: Quy trình tiếp nhận phản ánh POLYMATCH cần xác nhận
