insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ046','Thông tin doanh nghiệp cung cấp cho POLYMATCH có được bảo mật không?','Nhóm: Bảo mật
Câu hỏi chuẩn: Thông tin doanh nghiệp cung cấp cho POLYMATCH có được bảo mật không?
Cách hỏi tương đương: Dữ liệu công ty có an toàn không?; POLYMATCH có bảo mật thông tin không?; Ai được xem dữ liệu doanh nghiệp?
Câu trả lời chuẩn: Doanh nghiệp nên tham khảo chính sách bảo mật và điều khoản sử dụng của POLYMATCH để biết phạm vi thu thập, xử lý, lưu trữ và chia sẻ dữ liệu. Không nên cung cấp thông tin mật vượt quá phạm vi cần thiết khi thực hiện đánh giá.
Từ khóa: bảo mật, dữ liệu, thông tin doanh nghiệp, quyền riêng tư
Ngoại lệ: Không cam kết mức độ bảo mật hoặc tiêu chuẩn an toàn thông tin chưa được xác minh.
Nguồn: Chính sách bảo mật POLYMATCH – cần bổ sung
