insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ047','POLYMATCH có chia sẻ dữ liệu đánh giá của doanh nghiệp cho nhà cung cấp không?','Nhóm: Bảo mật
Câu hỏi chuẩn: POLYMATCH có chia sẻ dữ liệu đánh giá của doanh nghiệp cho nhà cung cấp không?
Cách hỏi tương đương: Nhà cung cấp có xem được kết quả DBI không?; Dữ liệu đánh giá có bị chia sẻ không?; Ai xem được kết quả của tôi?
Câu trả lời chuẩn: Việc chia sẻ dữ liệu cần tuân thủ chính sách bảo mật và cơ chế đồng ý của người dùng. Doanh nghiệp nên kiểm tra thông tin được chia sẻ trước khi xác nhận kết nối với nhà cung cấp.
Từ khóa: chia sẻ dữ liệu, kết quả DBI, nhà cung cấp
Ngoại lệ: Không khẳng định dữ liệu được chia sẻ hoặc không được chia sẻ khi chưa có quy định cụ thể.
Nguồn: Chính sách chia sẻ dữ liệu POLYMATCH – cần bổ sung
