insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ049','Tôi có nên cung cấp mật khẩu, tài khoản ngân hàng hoặc dữ liệu nội bộ cho chatbot không?','Nhóm: Bảo mật
Câu hỏi chuẩn: Tôi có nên cung cấp mật khẩu, tài khoản ngân hàng hoặc dữ liệu nội bộ cho chatbot không?
Cách hỏi tương đương: Có nên gửi mật khẩu cho chatbot không?; Chatbot có cần mã OTP không?; Tôi có thể gửi dữ liệu tài chính công ty không?
Câu trả lời chuẩn: Không. Bạn không nên cung cấp mật khẩu, mã OTP, thông tin tài khoản ngân hàng hoặc dữ liệu kinh doanh nhạy cảm qua chatbot. Chỉ cung cấp thông tin cần thiết cho mục đích hỗ trợ và đánh giá.
Từ khóa: mật khẩu, OTP, ngân hàng, dữ liệu nhạy cảm
Ngoại lệ: Nếu người dùng đã gửi thông tin nhạy cảm, chatbot không được lặp lại thông tin đó và cần hướng dẫn biện pháp bảo vệ tài khoản phù hợp.
Nguồn: Nguyên tắc an toàn dữ liệu chatbot POLYMATCH
