insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ051','Tôi đã hoàn thành đánh giá nhưng không thấy kết quả?','Nhóm: Sự cố
Câu hỏi chuẩn: Tôi đã hoàn thành đánh giá nhưng không thấy kết quả?
Cách hỏi tương đương: Làm xong DBI nhưng không có điểm; Không hiển thị kết quả đánh giá; Kết quả bị mất?
Câu trả lời chuẩn: Bạn hãy kiểm tra xem toàn bộ câu hỏi bắt buộc đã được hoàn thành và dữ liệu đã được gửi thành công hay chưa. Nếu vẫn không hiển thị kết quả, hãy liên hệ bộ phận hỗ trợ kèm thông tin tài khoản và ảnh chụp màn hình.
Từ khóa: không có kết quả, lỗi DBI, mất kết quả
Ngoại lệ: Không yêu cầu người dùng thực hiện lại toàn bộ đánh giá trước khi kiểm tra dữ liệu.
Nguồn: Quy trình xử lý lỗi DBI POLYMATCH cần xác nhận
