insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ052','Chatbot không trả lời được câu hỏi của tôi thì sao?','Nhóm: Sự cố
Câu hỏi chuẩn: Chatbot không trả lời được câu hỏi của tôi thì sao?
Cách hỏi tương đương: Chatbot trả lời sai; Chatbot không hiểu câu hỏi; Tôi cần gặp nhân viên tư vấn; Làm sao hỏi người thật?
Câu trả lời chuẩn: Nếu câu hỏi nằm ngoài phạm vi dữ liệu hiện có, chatbot nên thông báo rõ giới hạn thông tin và hướng dẫn bạn chuyển câu hỏi đến bộ phận hỗ trợ POLYMATCH để được tư vấn thêm.
Từ khóa: chatbot, không trả lời, chuyển nhân viên, tư vấn
Ngoại lệ: Bắt buộc chuyển tiếp nếu câu hỏi liên quan đến tranh chấp, pháp lý, dữ liệu nhạy cảm hoặc sự cố nghiêm trọng.
Nguồn: Quy trình chuyển tiếp CSKH POLYMATCH
