insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('FAQ053','Tôi muốn gửi góp ý hoặc phản ánh về nền tảng thì liên hệ ở đâu?','Nhóm: Sự cố
Câu hỏi chuẩn: Tôi muốn gửi góp ý hoặc phản ánh về nền tảng thì liên hệ ở đâu?
Cách hỏi tương đương: Gửi phản hồi cho POLYMATCH thế nào?; Muốn góp ý giao diện; Báo lỗi nền tảng ở đâu?
Câu trả lời chuẩn: Bạn có thể sử dụng kênh liên hệ hoặc biểu mẫu phản hồi được công bố trên nền tảng. Hãy mô tả cụ thể vấn đề, chức năng liên quan và kết quả mong muốn để đội ngũ hỗ trợ tiếp nhận hiệu quả hơn.
Từ khóa: góp ý, phản ánh, báo lỗi, liên hệ
Ngoại lệ: Nếu chưa có kênh tiếp nhận chính thức, chatbot cần thông báo và chuyển yêu cầu cho nhân viên phụ trách.
Nguồn: Quy trình tiếp nhận phản hồi POLYMATCH cần xác nhận
