insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG002','WMS (Warehouse Management System) · Quản lý kho','Lĩnh vực: Kho bãi
Chủ đề: Quản lý kho
Thuật ngữ: WMS (Warehouse Management System)
Định nghĩa: Hệ thống quản lý hoạt động kho như nhận hàng, put-away, lưu trữ, bổ sung, picking, packing, xuất hàng và kiểm kê.
Ví dụ thực tế: Quét mã hàng khi nhập kho, gán vị trí lưu trữ, tạo lệnh lấy hàng và cập nhật tồn kho theo giao dịch.
Cách tính KPI: Độ chính xác tồn kho = Số SKU-vị trí có số lượng hệ thống khớp kiểm đếm ÷ Tổng SKU-vị trí được kiểm đếm × 100%.
Đơn vị: %
Phạm vi: Chọn đơn vị đo nhất quán: SKU, SKU-vị trí hoặc dòng hàng; không trộn lẫn.
Nguồn: CSCMP glossary: https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx; ASCM SCOR: https://scor.ascm.org/performance/introduction
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Logistics',false,'https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx','["https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx", "https://scor.ascm.org/performance/introduction"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 5}, "fields": {"ID": "LOG002", "Lĩnh vực": "Kho bãi", "Chủ đề": "Quản lý kho", "Thuật ngữ": "WMS (Warehouse Management System)", "Định nghĩa": "Hệ thống quản lý hoạt động kho như nhận hàng, put-away, lưu trữ, bổ sung, picking, packing, xuất hàng và kiểm kê.", "Ví dụ thực tế": "Quét mã hàng khi nhập kho, gán vị trí lưu trữ, tạo lệnh lấy hàng và cập nhật tồn kho theo giao dịch.", "Cách tính KPI": "Độ chính xác tồn kho = Số SKU-vị trí có số lượng hệ thống khớp kiểm đếm ÷ Tổng SKU-vị trí được kiểm đếm × 100%.", "Đơn vị": "%", "Phạm vi": "Chọn đơn vị đo nhất quán: SKU, SKU-vị trí hoặc dòng hàng; không trộn lẫn.", "Nguồn": "CSCMP glossary: https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx; ASCM SCOR: https://scor.ascm.org/performance/introduction", "Người xác minh": "Chuyên gia kho vận", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG003','ERP (Enterprise Resource Planning) · Hoạch định nguồn lực','Lĩnh vực: Quản trị
Chủ đề: Hoạch định nguồn lực
Thuật ngữ: ERP (Enterprise Resource Planning)
Định nghĩa: Hệ thống hoạch định nguồn lực doanh nghiệp tích hợp dữ liệu và quy trình liên chức năng như tài chính, mua hàng, bán hàng, tồn kho, sản xuất và nhân sự tùy cấu hình.
Ví dụ thực tế: Đơn bán hàng tạo nhu cầu xuất kho; dữ liệu giao hàng và hóa đơn được liên kết với kế toán.
Cách tính KPI: Không có một công thức KPI ERP chung; đánh giá bằng tỷ lệ quy trình được số hóa, tỷ lệ dữ liệu đồng nhất, thời gian xử lý và tỷ lệ lỗi trước/sau.
Đơn vị: %, giờ, lỗi
Phạm vi: Phạm vi phụ thuộc module, cấu hình, tích hợp và mức độ sử dụng thực tế.
Nguồn: OECD Digitalisation of SMEs: https://www.oecd.org/en/topics/digitalisation-of-smes.html
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Logistics',false,'https://www.oecd.org/en/topics/digitalisation-of-smes.html','["https://www.oecd.org/en/topics/digitalisation-of-smes.html"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 6}, "fields": {"ID": "LOG003", "Lĩnh vực": "Quản trị", "Chủ đề": "Hoạch định nguồn lực", "Thuật ngữ": "ERP (Enterprise Resource Planning)", "Định nghĩa": "Hệ thống hoạch định nguồn lực doanh nghiệp tích hợp dữ liệu và quy trình liên chức năng như tài chính, mua hàng, bán hàng, tồn kho, sản xuất và nhân sự tùy cấu hình.", "Ví dụ thực tế": "Đơn bán hàng tạo nhu cầu xuất kho; dữ liệu giao hàng và hóa đơn được liên kết với kế toán.", "Cách tính KPI": "Không có một công thức KPI ERP chung; đánh giá bằng tỷ lệ quy trình được số hóa, tỷ lệ dữ liệu đồng nhất, thời gian xử lý và tỷ lệ lỗi trước/sau.", "Đơn vị": "%, giờ, lỗi", "Phạm vi": "Phạm vi phụ thuộc module, cấu hình, tích hợp và mức độ sử dụng thực tế.", "Nguồn": "OECD Digitalisation of SMEs: https://www.oecd.org/en/topics/digitalisation-of-smes.html", "Người xác minh": "Chuyên gia chuyển đổi số", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG004','Logistics management · Quản lý logistics','Lĩnh vực: Dịch vụ logistics
Chủ đề: Quản lý logistics
Thuật ngữ: Logistics management
Định nghĩa: Theo CSCMP, quản lý logistics là một phần của SCM, hoạch định, triển khai và kiểm soát dòng lưu chuyển/lưu trữ xuôi-ngược hiệu quả của hàng hóa, dịch vụ và thông tin liên quan từ điểm xuất phát đến điểm tiêu dùng để đáp ứng yêu cầu khách hàng.
Ví dụ thực tế: Điều phối vận tải đầu vào, lưu kho, xử lý đơn, giao hàng và logistics ngược.
Cách tính KPI: Không có KPI đơn nhất; thường theo dõi chi phí vận tải, thời gian chu kỳ, giao đúng hạn, độ chính xác đơn và tồn kho.
Đơn vị: Tùy KPI
Phạm vi: Phân biệt logistics với SCM: SCM có phạm vi rộng hơn, gồm tìm nguồn cung, chuyển đổi/sản xuất và phối hợp đối tác.
Nguồn: CSCMP Definitions and Glossary: https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Đã biên soạn – cần duyệt','Logistics',false,'https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx','["https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 7}, "fields": {"ID": "LOG004", "Lĩnh vực": "Dịch vụ logistics", "Chủ đề": "Quản lý logistics", "Thuật ngữ": "Logistics management", "Định nghĩa": "Theo CSCMP, quản lý logistics là một phần của SCM, hoạch định, triển khai và kiểm soát dòng lưu chuyển/lưu trữ xuôi-ngược hiệu quả của hàng hóa, dịch vụ và thông tin liên quan từ điểm xuất phát đến điểm tiêu dùng để đáp ứng yêu cầu khách hàng.", "Ví dụ thực tế": "Điều phối vận tải đầu vào, lưu kho, xử lý đơn, giao hàng và logistics ngược.", "Cách tính KPI": "Không có KPI đơn nhất; thường theo dõi chi phí vận tải, thời gian chu kỳ, giao đúng hạn, độ chính xác đơn và tồn kho.", "Đơn vị": "Tùy KPI", "Phạm vi": "Phân biệt logistics với SCM: SCM có phạm vi rộng hơn, gồm tìm nguồn cung, chuyển đổi/sản xuất và phối hợp đối tác.", "Nguồn": "CSCMP Definitions and Glossary: https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx", "Người xác minh": "Chuyên gia logistics", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Đã biên soạn – cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG005','Supply Chain Management (SCM) · Quản trị chuỗi cung ứng','Lĩnh vực: Chuỗi cung ứng
Chủ đề: Quản trị chuỗi cung ứng
Thuật ngữ: Supply Chain Management (SCM)
Định nghĩa: SCM bao gồm hoạch định và quản lý hoạt động tìm nguồn cung, mua sắm, chuyển đổi/sản xuất và logistics; đồng thời phối hợp với nhà cung cấp, trung gian, nhà cung cấp dịch vụ và khách hàng.
Ví dụ thực tế: Phối hợp dự báo nhu cầu, kế hoạch mua hàng, sản xuất, tồn kho, vận chuyển và giao hàng.
Cách tính KPI: Có thể dùng bộ KPI SCOR: độ tin cậy, khả năng đáp ứng, linh hoạt, chi phí, lợi nhuận, tài sản, môi trường và xã hội.
Đơn vị: Theo từng KPI
Phạm vi: Không đồng nhất SCM với riêng vận tải hoặc kho bãi.
Nguồn: CSCMP: https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx; ASCM SCOR: https://scor.ascm.org/performance/introduction
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Đã biên soạn – cần duyệt','Logistics',false,'https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx','["https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx", "https://scor.ascm.org/performance/introduction"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 8}, "fields": {"ID": "LOG005", "Lĩnh vực": "Chuỗi cung ứng", "Chủ đề": "Quản trị chuỗi cung ứng", "Thuật ngữ": "Supply Chain Management (SCM)", "Định nghĩa": "SCM bao gồm hoạch định và quản lý hoạt động tìm nguồn cung, mua sắm, chuyển đổi/sản xuất và logistics; đồng thời phối hợp với nhà cung cấp, trung gian, nhà cung cấp dịch vụ và khách hàng.", "Ví dụ thực tế": "Phối hợp dự báo nhu cầu, kế hoạch mua hàng, sản xuất, tồn kho, vận chuyển và giao hàng.", "Cách tính KPI": "Có thể dùng bộ KPI SCOR: độ tin cậy, khả năng đáp ứng, linh hoạt, chi phí, lợi nhuận, tài sản, môi trường và xã hội.", "Đơn vị": "Theo từng KPI", "Phạm vi": "Không đồng nhất SCM với riêng vận tải hoặc kho bãi.", "Nguồn": "CSCMP: https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx; ASCM SCOR: https://scor.ascm.org/performance/introduction", "Người xác minh": "Chuyên gia SCM", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Đã biên soạn – cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG006','On-time Delivery (OTD) · Giao hàng đúng hạn','Lĩnh vực: Vận tải
Chủ đề: Giao hàng đúng hạn
Thuật ngữ: On-time Delivery (OTD)
Định nghĩa: Tỷ lệ đơn hàng/chuyến giao trong khoảng thời gian cam kết với khách hàng.
Ví dụ thực tế: Đơn giao trước hoặc đúng thời điểm hẹn được tính đạt nếu thỏa định nghĩa doanh nghiệp.
Cách tính KPI: OTD = Số đơn giao đúng hạn ÷ Tổng số đơn đến hạn trong kỳ × 100%.
Đơn vị: %
Phạm vi: Cần quy định mốc tính (đến cổng, giao đủ, ký POD), múi giờ, đơn hủy và giao nhiều đợt.
Nguồn: ASCM SCOR reliability: https://scor.ascm.org/performance/reliability/RL.1.1
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Logistics',false,'https://scor.ascm.org/performance/reliability/RL.1.1','["https://scor.ascm.org/performance/reliability/RL.1.1"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 9}, "fields": {"ID": "LOG006", "Lĩnh vực": "Vận tải", "Chủ đề": "Giao hàng đúng hạn", "Thuật ngữ": "On-time Delivery (OTD)", "Định nghĩa": "Tỷ lệ đơn hàng/chuyến giao trong khoảng thời gian cam kết với khách hàng.", "Ví dụ thực tế": "Đơn giao trước hoặc đúng thời điểm hẹn được tính đạt nếu thỏa định nghĩa doanh nghiệp.", "Cách tính KPI": "OTD = Số đơn giao đúng hạn ÷ Tổng số đơn đến hạn trong kỳ × 100%.", "Đơn vị": "%", "Phạm vi": "Cần quy định mốc tính (đến cổng, giao đủ, ký POD), múi giờ, đơn hủy và giao nhiều đợt.", "Nguồn": "ASCM SCOR reliability: https://scor.ascm.org/performance/reliability/RL.1.1", "Người xác minh": "Chuyên gia vận tải", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG007','Perfect Order Fulfillment · Hoàn thành đơn hàng hoàn hảo','Lĩnh vực: Đơn hàng
Chủ đề: Hoàn thành đơn hàng hoàn hảo
Thuật ngữ: Perfect Order Fulfillment
Định nghĩa: Tỷ lệ đơn đáp ứng đồng thời yêu cầu về đúng sản phẩm/số lượng, đúng thời gian/địa điểm/khách hàng, chứng từ chính xác và tình trạng hàng hóa đạt yêu cầu.
Ví dụ thực tế: Đơn giao đủ, đúng hẹn, không hư hỏng, chứng từ đầy đủ và chính xác.
Cách tính KPI: Perfect Order Fulfillment = Số đơn hoàn hảo ÷ Tổng số đơn đủ điều kiện × 100%.
Đơn vị: %
Phạm vi: Theo ASCM, chỉ cần một thành phần không đạt thì đơn không được tính hoàn hảo; cần xác định quy tắc loại đơn hủy.
Nguồn: ASCM SCOR RL.1.1: https://scor.ascm.org/performance/reliability/RL.1.1
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Đã biên soạn – cần duyệt','Logistics',false,'https://scor.ascm.org/performance/reliability/RL.1.1','["https://scor.ascm.org/performance/reliability/RL.1.1"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 10}, "fields": {"ID": "LOG007", "Lĩnh vực": "Đơn hàng", "Chủ đề": "Hoàn thành đơn hàng hoàn hảo", "Thuật ngữ": "Perfect Order Fulfillment", "Định nghĩa": "Tỷ lệ đơn đáp ứng đồng thời yêu cầu về đúng sản phẩm/số lượng, đúng thời gian/địa điểm/khách hàng, chứng từ chính xác và tình trạng hàng hóa đạt yêu cầu.", "Ví dụ thực tế": "Đơn giao đủ, đúng hẹn, không hư hỏng, chứng từ đầy đủ và chính xác.", "Cách tính KPI": "Perfect Order Fulfillment = Số đơn hoàn hảo ÷ Tổng số đơn đủ điều kiện × 100%.", "Đơn vị": "%", "Phạm vi": "Theo ASCM, chỉ cần một thành phần không đạt thì đơn không được tính hoàn hảo; cần xác định quy tắc loại đơn hủy.", "Nguồn": "ASCM SCOR RL.1.1: https://scor.ascm.org/performance/reliability/RL.1.1", "Người xác minh": "Chuyên gia vận hành", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Đã biên soạn – cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG008','Inventory Turnover · Vòng quay hàng tồn kho','Lĩnh vực: Kho bãi
Chủ đề: Vòng quay hàng tồn kho
Thuật ngữ: Inventory Turnover
Định nghĩa: Chỉ tiêu thể hiện số lần hàng tồn kho được luân chuyển trong kỳ.
Ví dụ thực tế: So sánh giá vốn hàng bán năm với tồn kho bình quân năm để đánh giá tốc độ luân chuyển.
Cách tính KPI: Inventory Turnover = Giá vốn hàng bán trong kỳ ÷ Giá trị tồn kho bình quân trong kỳ.
Đơn vị: Lần/kỳ
Phạm vi: Dùng cùng cơ sở định giá; tồn kho bình quân nên tính theo nhiều thời điểm nếu biến động lớn.
Nguồn: ASCM SCOR performance (asset/cost metrics): https://scor.ascm.org/performance/introduction
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Logistics',false,'https://scor.ascm.org/performance/introduction','["https://scor.ascm.org/performance/introduction"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 11}, "fields": {"ID": "LOG008", "Lĩnh vực": "Kho bãi", "Chủ đề": "Vòng quay hàng tồn kho", "Thuật ngữ": "Inventory Turnover", "Định nghĩa": "Chỉ tiêu thể hiện số lần hàng tồn kho được luân chuyển trong kỳ.", "Ví dụ thực tế": "So sánh giá vốn hàng bán năm với tồn kho bình quân năm để đánh giá tốc độ luân chuyển.", "Cách tính KPI": "Inventory Turnover = Giá vốn hàng bán trong kỳ ÷ Giá trị tồn kho bình quân trong kỳ.", "Đơn vị": "Lần/kỳ", "Phạm vi": "Dùng cùng cơ sở định giá; tồn kho bình quân nên tính theo nhiều thời điểm nếu biến động lớn.", "Nguồn": "ASCM SCOR performance (asset/cost metrics): https://scor.ascm.org/performance/introduction", "Người xác minh": "Chuyên gia tài chính-kho", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG009','Order Fulfillment Cycle Time · Thời gian chu kỳ hoàn thành đơn','Lĩnh vực: Đơn hàng
Chủ đề: Thời gian chu kỳ hoàn thành đơn
Thuật ngữ: Order Fulfillment Cycle Time
Định nghĩa: Khoảng thời gian từ khi nhận đơn hàng hợp lệ đến khi hoàn tất giao hàng theo định nghĩa đã thống nhất.
Ví dụ thực tế: Từ thời điểm đơn được xác nhận đến khi khách ký nhận đủ hàng.
Cách tính KPI: Chu kỳ đơn trung bình = Tổng thời gian hoàn thành của các đơn đủ điều kiện ÷ Số đơn đủ điều kiện.
Đơn vị: Giờ/ngày
Phạm vi: Phải công bố điểm bắt đầu/kết thúc, đơn vị thời gian và cách xử lý đơn đang mở.
Nguồn: ASCM SCOR Responsiveness: https://scor.ascm.org/performance/introduction
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Logistics',false,'https://scor.ascm.org/performance/introduction','["https://scor.ascm.org/performance/introduction"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 12}, "fields": {"ID": "LOG009", "Lĩnh vực": "Đơn hàng", "Chủ đề": "Thời gian chu kỳ hoàn thành đơn", "Thuật ngữ": "Order Fulfillment Cycle Time", "Định nghĩa": "Khoảng thời gian từ khi nhận đơn hàng hợp lệ đến khi hoàn tất giao hàng theo định nghĩa đã thống nhất.", "Ví dụ thực tế": "Từ thời điểm đơn được xác nhận đến khi khách ký nhận đủ hàng.", "Cách tính KPI": "Chu kỳ đơn trung bình = Tổng thời gian hoàn thành của các đơn đủ điều kiện ÷ Số đơn đủ điều kiện.", "Đơn vị": "Giờ/ngày", "Phạm vi": "Phải công bố điểm bắt đầu/kết thúc, đơn vị thời gian và cách xử lý đơn đang mở.", "Nguồn": "ASCM SCOR Responsiveness: https://scor.ascm.org/performance/introduction", "Người xác minh": "Chuyên gia vận hành", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG010','Stockout Rate · Tỷ lệ hết hàng','Lĩnh vực: Tồn kho
Chủ đề: Tỷ lệ hết hàng
Thuật ngữ: Stockout Rate
Định nghĩa: Tỷ lệ dòng hàng hoặc yêu cầu có nhu cầu nhưng không thể đáp ứng từ tồn kho khả dụng tại thời điểm yêu cầu.
Ví dụ thực tế: Đơn hàng yêu cầu 10 SKU nhưng một SKU không có hàng khả dụng.
Cách tính KPI: Stockout Rate = Số dòng hàng bị hết hàng ÷ Tổng dòng hàng có nhu cầu × 100%.
Đơn vị: %
Phạm vi: Có nhiều cách định nghĩa theo SKU, ngày hoặc dòng đơn; phải chọn một phương pháp nhất quán.
Nguồn: ASCM SCOR metrics framework: https://scor.ascm.org/performance/introduction
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Logistics',false,'https://scor.ascm.org/performance/introduction','["https://scor.ascm.org/performance/introduction"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 13}, "fields": {"ID": "LOG010", "Lĩnh vực": "Tồn kho", "Chủ đề": "Tỷ lệ hết hàng", "Thuật ngữ": "Stockout Rate", "Định nghĩa": "Tỷ lệ dòng hàng hoặc yêu cầu có nhu cầu nhưng không thể đáp ứng từ tồn kho khả dụng tại thời điểm yêu cầu.", "Ví dụ thực tế": "Đơn hàng yêu cầu 10 SKU nhưng một SKU không có hàng khả dụng.", "Cách tính KPI": "Stockout Rate = Số dòng hàng bị hết hàng ÷ Tổng dòng hàng có nhu cầu × 100%.", "Đơn vị": "%", "Phạm vi": "Có nhiều cách định nghĩa theo SKU, ngày hoặc dòng đơn; phải chọn một phương pháp nhất quán.", "Nguồn": "ASCM SCOR metrics framework: https://scor.ascm.org/performance/introduction", "Người xác minh": "Chuyên gia tồn kho", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG011','Supplier On-time Delivery · Tỷ lệ giao hàng nhà cung cấp đúng hạn','Lĩnh vực: Mua hàng
Chủ đề: Tỷ lệ giao hàng nhà cung cấp đúng hạn
Thuật ngữ: Supplier On-time Delivery
Định nghĩa: Tỷ lệ đơn/dòng đơn mua hàng được nhà cung cấp giao đúng ngày cam kết ban đầu.
Ví dụ thực tế: Đo tỷ lệ lô nguyên liệu nhận đúng ngày hẹn để đánh giá độ tin cậy nhà cung cấp.
Cách tính KPI: Supplier OTD = Số đơn/dòng đơn nhận đúng hạn ÷ Tổng đơn/dòng đơn đến hạn × 100%.
Đơn vị: %
Phạm vi: Cần thống nhất tính theo đơn hay dòng đơn, ngày cam kết ban đầu hay ngày sửa đổi.
Nguồn: ASCM SCOR reliability: https://scor.ascm.org/performance/reliability/RL.1.1
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Logistics',false,'https://scor.ascm.org/performance/reliability/RL.1.1','["https://scor.ascm.org/performance/reliability/RL.1.1"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 14}, "fields": {"ID": "LOG011", "Lĩnh vực": "Mua hàng", "Chủ đề": "Tỷ lệ giao hàng nhà cung cấp đúng hạn", "Thuật ngữ": "Supplier On-time Delivery", "Định nghĩa": "Tỷ lệ đơn/dòng đơn mua hàng được nhà cung cấp giao đúng ngày cam kết ban đầu.", "Ví dụ thực tế": "Đo tỷ lệ lô nguyên liệu nhận đúng ngày hẹn để đánh giá độ tin cậy nhà cung cấp.", "Cách tính KPI": "Supplier OTD = Số đơn/dòng đơn nhận đúng hạn ÷ Tổng đơn/dòng đơn đến hạn × 100%.", "Đơn vị": "%", "Phạm vi": "Cần thống nhất tính theo đơn hay dòng đơn, ngày cam kết ban đầu hay ngày sửa đổi.", "Nguồn": "ASCM SCOR reliability: https://scor.ascm.org/performance/reliability/RL.1.1", "Người xác minh": "Chuyên gia mua hàng", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG012','Load Utilization · Tỷ lệ sử dụng tải trọng','Lĩnh vực: Vận tải
Chủ đề: Tỷ lệ sử dụng tải trọng
Thuật ngữ: Load Utilization
Định nghĩa: Mức độ sử dụng sức chứa hoặc tải trọng phương tiện so với năng lực khả dụng.
Ví dụ thực tế: So sánh trọng lượng hàng thực chở với tải trọng cho phép của xe.
Cách tính KPI: Utilization theo khối lượng = Khối lượng hàng thực chở ÷ Tải trọng khả dụng × 100%.
Đơn vị: %
Phạm vi: Không vượt giới hạn tải trọng pháp luật; nếu hàng cồng kềnh nên đo theo thể tích hoặc pallet, không chỉ khối lượng.
Nguồn: UNCTAD Review of Maritime Transport 2024 (hiệu quả vận tải và đội tàu): https://unctad.org/publication/review-maritime-transport-2024
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Logistics',false,'https://unctad.org/publication/review-maritime-transport-2024','["https://unctad.org/publication/review-maritime-transport-2024"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 15}, "fields": {"ID": "LOG012", "Lĩnh vực": "Vận tải", "Chủ đề": "Tỷ lệ sử dụng tải trọng", "Thuật ngữ": "Load Utilization", "Định nghĩa": "Mức độ sử dụng sức chứa hoặc tải trọng phương tiện so với năng lực khả dụng.", "Ví dụ thực tế": "So sánh trọng lượng hàng thực chở với tải trọng cho phép của xe.", "Cách tính KPI": "Utilization theo khối lượng = Khối lượng hàng thực chở ÷ Tải trọng khả dụng × 100%.", "Đơn vị": "%", "Phạm vi": "Không vượt giới hạn tải trọng pháp luật; nếu hàng cồng kềnh nên đo theo thể tích hoặc pallet, không chỉ khối lượng.", "Nguồn": "UNCTAD Review of Maritime Transport 2024 (hiệu quả vận tải và đội tàu): https://unctad.org/publication/review-maritime-transport-2024", "Người xác minh": "Chuyên gia vận tải", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG013','GHG Emissions · Phát thải khí nhà kính','Lĩnh vực: Logistics xanh
Chủ đề: Phát thải khí nhà kính
Thuật ngữ: GHG Emissions
Định nghĩa: Lượng phát thải khí nhà kính phát sinh từ hoạt động được xác định trong ranh giới đo lường và quy đổi về CO2 tương đương.
Ví dụ thực tế: Tính phát thải từ nhiên liệu xe, điện kho hoặc hoạt động vận tải thuê ngoài theo dữ liệu hoạt động và hệ số phát thải phù hợp.
Cách tính KPI: Phát thải = Dữ liệu hoạt động × Hệ số phát thải; tổng CO2e = tổng các khí sau quy đổi theo tiềm năng nóng lên toàn cầu áp dụng.
Đơn vị: kg hoặc tấn CO2e
Phạm vi: Cần nêu ranh giới tổ chức/hoạt động, kỳ báo cáo, hệ số và nguồn hệ số; không so sánh nếu phương pháp khác nhau.
Nguồn: ASCM SCOR Environmental metrics: https://scor.ascm.org/performance/introduction
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Logistics',false,'https://scor.ascm.org/performance/introduction','["https://scor.ascm.org/performance/introduction"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 16}, "fields": {"ID": "LOG013", "Lĩnh vực": "Logistics xanh", "Chủ đề": "Phát thải khí nhà kính", "Thuật ngữ": "GHG Emissions", "Định nghĩa": "Lượng phát thải khí nhà kính phát sinh từ hoạt động được xác định trong ranh giới đo lường và quy đổi về CO2 tương đương.", "Ví dụ thực tế": "Tính phát thải từ nhiên liệu xe, điện kho hoặc hoạt động vận tải thuê ngoài theo dữ liệu hoạt động và hệ số phát thải phù hợp.", "Cách tính KPI": "Phát thải = Dữ liệu hoạt động × Hệ số phát thải; tổng CO2e = tổng các khí sau quy đổi theo tiềm năng nóng lên toàn cầu áp dụng.", "Đơn vị": "kg hoặc tấn CO2e", "Phạm vi": "Cần nêu ranh giới tổ chức/hoạt động, kỳ báo cáo, hệ số và nguồn hệ số; không so sánh nếu phương pháp khác nhau.", "Nguồn": "ASCM SCOR Environmental metrics: https://scor.ascm.org/performance/introduction", "Người xác minh": "Chuyên gia ESG", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG014','Logistics Performance Index (LPI) · Chỉ số hiệu quả logistics','Lĩnh vực: Vận tải quốc tế
Chủ đề: Chỉ số hiệu quả logistics
Thuật ngữ: Logistics Performance Index (LPI)
Định nghĩa: Chỉ số của World Bank đánh giá hiệu quả logistics quốc gia. LPI 2023 dựa trên khảo sát chuyên gia logistics quốc tế với sáu thành phần; LPI 2.0 hiện sử dụng 21 chỉ báo quốc gia và không đưa ra một thứ hạng tổng hợp duy nhất.
Ví dụ thực tế: Dùng để tham khảo bối cảnh logistics quốc gia, không dùng thay KPI vận hành của một doanh nghiệp.
Cách tính KPI: Không tự tính từ dữ liệu doanh nghiệp; sử dụng đúng bộ dữ liệu, phiên bản và phương pháp LPI tương ứng.
Đơn vị: Điểm/chỉ báo
Phạm vi: Phân biệt LPI 2023 với LPI 2.0; không trộn điểm hoặc thứ hạng giữa các phiên bản.
Nguồn: World Bank LPI methodology: https://lpi.worldbank.org/en/about/methodology; LPI 2023: https://www.worldbank.org/en/news/press-release/2023/04/21/world-bank-releases-logistics-performance-index-2023
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Đã biên soạn – cần duyệt','Logistics',false,'https://lpi.worldbank.org/en/about/methodology','["https://lpi.worldbank.org/en/about/methodology", "https://www.worldbank.org/en/news/press-release/2023/04/21/world-bank-releases-logistics-performance-index-2023"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 17}, "fields": {"ID": "LOG014", "Lĩnh vực": "Vận tải quốc tế", "Chủ đề": "Chỉ số hiệu quả logistics", "Thuật ngữ": "Logistics Performance Index (LPI)", "Định nghĩa": "Chỉ số của World Bank đánh giá hiệu quả logistics quốc gia. LPI 2023 dựa trên khảo sát chuyên gia logistics quốc tế với sáu thành phần; LPI 2.0 hiện sử dụng 21 chỉ báo quốc gia và không đưa ra một thứ hạng tổng hợp duy nhất.", "Ví dụ thực tế": "Dùng để tham khảo bối cảnh logistics quốc gia, không dùng thay KPI vận hành của một doanh nghiệp.", "Cách tính KPI": "Không tự tính từ dữ liệu doanh nghiệp; sử dụng đúng bộ dữ liệu, phiên bản và phương pháp LPI tương ứng.", "Đơn vị": "Điểm/chỉ báo", "Phạm vi": "Phân biệt LPI 2023 với LPI 2.0; không trộn điểm hoặc thứ hạng giữa các phiên bản.", "Nguồn": "World Bank LPI methodology: https://lpi.worldbank.org/en/about/methodology; LPI 2023: https://www.worldbank.org/en/news/press-release/2023/04/21/world-bank-releases-logistics-performance-index-2023", "Người xác minh": "Chuyên gia nghiên cứu", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Đã biên soạn – cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG015','Supply Chain Visibility · Khả năng hiển thị chuỗi cung ứng','Lĩnh vực: Công nghệ logistics
Chủ đề: Khả năng hiển thị chuỗi cung ứng
Thuật ngữ: Supply Chain Visibility
Định nghĩa: Khả năng theo dõi và tiếp cận thông tin về vị trí, trạng thái, thời gian và quá trình di chuyển của hàng hóa xuyên suốt các công đoạn trong chuỗi cung ứng.
Ví dụ thực tế: Doanh nghiệp có thể theo dõi lô hàng từ nhà máy, qua kho trung chuyển đến điểm giao cuối cùng.
Cách tính KPI: Tỷ lệ lô hàng có dữ liệu theo dõi đầy đủ = (Số lô hàng có đầy đủ sự kiện theo dõi bắt buộc / Tổng số lô hàng) × 100%.
Đơn vị: %
Phạm vi: Vận tải, kho bãi, giao nhận, chuỗi cung ứng
Nguồn: GS1 – EPCIS Standard 

GS1 GO Customer Service Portal+1
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Logistics',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 18}, "fields": {"ID": "LOG015", "Lĩnh vực": "Công nghệ logistics", "Chủ đề": "Khả năng hiển thị chuỗi cung ứng", "Thuật ngữ": "Supply Chain Visibility", "Định nghĩa": "Khả năng theo dõi và tiếp cận thông tin về vị trí, trạng thái, thời gian và quá trình di chuyển của hàng hóa xuyên suốt các công đoạn trong chuỗi cung ứng.", "Ví dụ thực tế": "Doanh nghiệp có thể theo dõi lô hàng từ nhà máy, qua kho trung chuyển đến điểm giao cuối cùng.", "Cách tính KPI": "Tỷ lệ lô hàng có dữ liệu theo dõi đầy đủ = (Số lô hàng có đầy đủ sự kiện theo dõi bắt buộc / Tổng số lô hàng) × 100%.", "Đơn vị": "%", "Phạm vi": "Vận tải, kho bãi, giao nhận, chuỗi cung ứng", "Nguồn": "GS1 – EPCIS Standard \n\nGS1 GO Customer Service Portal+1", "Người xác minh": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG016','Traceability · Truy xuất nguồn gốc','Lĩnh vực: Công nghệ logistics
Chủ đề: Truy xuất nguồn gốc
Thuật ngữ: Traceability
Định nghĩa: Khả năng xác định và theo dõi lịch sử, vị trí, nguồn gốc và trạng thái của sản phẩm trong các giai đoạn của chuỗi cung ứng.
Ví dụ thực tế: Doanh nghiệp thực phẩm truy xuất được lô xoài từ vùng trồng, cơ sở đóng gói đến kho phân phối.
Cách tính KPI: Tỷ lệ lô hàng truy xuất được = (Số lô hàng có thể truy xuất đầy đủ thông tin theo yêu cầu / Tổng số lô hàng được kiểm tra) × 100%.
Đơn vị: %
Phạm vi: Thực phẩm, nông sản, dược phẩm, hàng tiêu dùng
Nguồn: GS1 – EPCIS Standard 

support.gs1.org+1
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Logistics',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 19}, "fields": {"ID": "LOG016", "Lĩnh vực": "Công nghệ logistics", "Chủ đề": "Truy xuất nguồn gốc", "Thuật ngữ": "Traceability", "Định nghĩa": "Khả năng xác định và theo dõi lịch sử, vị trí, nguồn gốc và trạng thái của sản phẩm trong các giai đoạn của chuỗi cung ứng.", "Ví dụ thực tế": "Doanh nghiệp thực phẩm truy xuất được lô xoài từ vùng trồng, cơ sở đóng gói đến kho phân phối.", "Cách tính KPI": "Tỷ lệ lô hàng truy xuất được = (Số lô hàng có thể truy xuất đầy đủ thông tin theo yêu cầu / Tổng số lô hàng được kiểm tra) × 100%.", "Đơn vị": "%", "Phạm vi": "Thực phẩm, nông sản, dược phẩm, hàng tiêu dùng", "Nguồn": "GS1 – EPCIS Standard \n\nsupport.gs1.org+1", "Người xác minh": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG017','Container Dwell Time · Thời gian lưu container tại cảng','Lĩnh vực: Logistics quốc tế
Chủ đề: Thời gian lưu container tại cảng
Thuật ngữ: Container Dwell Time
Định nghĩa: Khoảng thời gian container lưu lại trong khu vực cảng theo các mốc bắt đầu và kết thúc được xác định. Đối với container nhập khẩu, có thể đo từ khi container đến cảng đến khi rời cảng.
Ví dụ thực tế: Container nhập khẩu đến cảng ngày 1/11 và rời cảng ngày 5/11, thời gian lưu là 4 ngày nếu tính theo chênh lệch ngày.
Cách tính KPI: Dwell Time = Thời điểm container rời cảng − Thời điểm container đến cảng.
Đơn vị: Giờ, ngày
Phạm vi: Cảng biển, logistics quốc tế, xuất nhập khẩu
Nguồn: World Bank – LPI 2.0 Methodology 

lpi.worldbank.org+1
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Logistics',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 20}, "fields": {"ID": "LOG017", "Lĩnh vực": "Logistics quốc tế", "Chủ đề": "Thời gian lưu container tại cảng", "Thuật ngữ": "Container Dwell Time", "Định nghĩa": "Khoảng thời gian container lưu lại trong khu vực cảng theo các mốc bắt đầu và kết thúc được xác định. Đối với container nhập khẩu, có thể đo từ khi container đến cảng đến khi rời cảng.", "Ví dụ thực tế": "Container nhập khẩu đến cảng ngày 1/11 và rời cảng ngày 5/11, thời gian lưu là 4 ngày nếu tính theo chênh lệch ngày.", "Cách tính KPI": "Dwell Time = Thời điểm container rời cảng − Thời điểm container đến cảng.", "Đơn vị": "Giờ, ngày", "Phạm vi": "Cảng biển, logistics quốc tế, xuất nhập khẩu", "Nguồn": "World Bank – LPI 2.0 Methodology \n\nlpi.worldbank.org+1", "Người xác minh": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG018','3PL (Third-Party Logistics) · Thuê ngoài logistics','Lĩnh vực: Logistics tổng quan
Chủ đề: Thuê ngoài logistics
Thuật ngữ: 3PL (Third-Party Logistics)
Định nghĩa: Dịch vụ logistics bên thứ ba, trong đó doanh nghiệp thuê đơn vị chuyên nghiệp thực hiện một hoặc nhiều hoạt động như vận tải, kho bãi, phân phối và quản lý đơn hàng.
Ví dụ thực tế: Một doanh nghiệp sản xuất thuê đơn vị logistics bên ngoài quản lý kho và vận chuyển hàng đến đại lý.
Cách tính KPI: Không áp dụng trực tiếp. Có thể đánh giá nhà cung cấp 3PL qua OTD, OTIF, chi phí mỗi lô hàng và tỷ lệ hư hỏng.
Đơn vị: —
Phạm vi: Vận tải, kho bãi, phân phối, giao nhận
Nguồn: WHO – Technical Report Series, Glossary; CSCMP 

usp.org+1
