insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG019','4PL (Fourth-Party Logistics) · Quản lý logistics tích hợp','Lĩnh vực: Logistics tổng quan
Chủ đề: Quản lý logistics tích hợp
Thuật ngữ: 4PL (Fourth-Party Logistics)
Định nghĩa: Đơn vị cung cấp dịch vụ quản lý và điều phối tổng thể mạng lưới logistics của khách hàng, có thể quản lý nhiều nhà cung cấp 3PL, hãng vận tải và các bên liên quan.
Ví dụ thực tế: Một doanh nghiệp thuê 4PL điều phối nhiều đơn vị vận tải, kho thuê ngoài và hoạt động giao nhận trên toàn quốc.
Cách tính KPI: Không áp dụng trực tiếp. Có thể đánh giá thông qua tổng chi phí logistics, mức độ đáp ứng dịch vụ và hiệu quả phối hợp các nhà cung cấp.
Đơn vị: —
Phạm vi: Quản lý mạng lưới logistics
Nguồn: WHO – Technical Report Series, Glossary 

usp.org
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Logistics',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 22}, "fields": {"ID": "LOG019", "Lĩnh vực": "Logistics tổng quan", "Chủ đề": "Quản lý logistics tích hợp", "Thuật ngữ": "4PL (Fourth-Party Logistics)", "Định nghĩa": "Đơn vị cung cấp dịch vụ quản lý và điều phối tổng thể mạng lưới logistics của khách hàng, có thể quản lý nhiều nhà cung cấp 3PL, hãng vận tải và các bên liên quan.", "Ví dụ thực tế": "Một doanh nghiệp thuê 4PL điều phối nhiều đơn vị vận tải, kho thuê ngoài và hoạt động giao nhận trên toàn quốc.", "Cách tính KPI": "Không áp dụng trực tiếp. Có thể đánh giá thông qua tổng chi phí logistics, mức độ đáp ứng dịch vụ và hiệu quả phối hợp các nhà cung cấp.", "Đơn vị": "—", "Phạm vi": "Quản lý mạng lưới logistics", "Nguồn": "WHO – Technical Report Series, Glossary \n\nusp.org", "Người xác minh": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG020','Freight Forwarding · Giao nhận vận tải','Lĩnh vực: Logistics tổng quan
Chủ đề: Giao nhận vận tải
Thuật ngữ: Freight Forwarding
Định nghĩa: Hoạt động tổ chức và điều phối việc vận chuyển hàng hóa cho khách hàng, bao gồm lựa chọn phương thức vận tải, đặt chỗ, xử lý chứng từ và phối hợp các bên liên quan.
Ví dụ thực tế: Công ty giao nhận tổ chức vận chuyển container từ Hải Phòng đến Hamburg, phối hợp hãng tàu và xử lý chứng từ xuất khẩu.
Cách tính KPI: Không có công thức KPI duy nhất. Có thể theo dõi tỷ lệ lô hàng đúng lịch, chi phí mỗi lô và tỷ lệ sai sót chứng từ.
Đơn vị: %, VNĐ/lô hàng
Phạm vi: Giao nhận, vận tải quốc tế, xuất nhập khẩu
Nguồn: CSCMP – Logistics Management Definitions 

cscmp.org
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Logistics',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Logistics", "row": 23}, "fields": {"ID": "LOG020", "Lĩnh vực": "Logistics tổng quan", "Chủ đề": "Giao nhận vận tải", "Thuật ngữ": "Freight Forwarding", "Định nghĩa": "Hoạt động tổ chức và điều phối việc vận chuyển hàng hóa cho khách hàng, bao gồm lựa chọn phương thức vận tải, đặt chỗ, xử lý chứng từ và phối hợp các bên liên quan.", "Ví dụ thực tế": "Công ty giao nhận tổ chức vận chuyển container từ Hải Phòng đến Hamburg, phối hợp hãng tàu và xử lý chứng từ xuất khẩu.", "Cách tính KPI": "Không có công thức KPI duy nhất. Có thể theo dõi tỷ lệ lô hàng đúng lịch, chi phí mỗi lô và tỷ lệ sai sót chứng từ.", "Đơn vị": "%, VNĐ/lô hàng", "Phạm vi": "Giao nhận, vận tải quốc tế, xuất nhập khẩu", "Nguồn": "CSCMP – Logistics Management Definitions \n\ncscmp.org", "Người xác minh": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG021','Freight Consolidation · Gom hàng','Lĩnh vực: Logistics tổng quan
Chủ đề: Gom hàng
Thuật ngữ: Freight Consolidation
Định nghĩa: Hoạt động tập hợp nhiều lô hàng nhỏ thành một lô hàng lớn hơn để tối ưu không gian vận tải và chi phí vận chuyển.
Ví dụ thực tế: Ba doanh nghiệp có hàng xuất khẩu chưa đủ một container cùng sử dụng phương án LCL để gom hàng.
Cách tính KPI: Tỷ lệ sử dụng tải trọng = (Khối lượng hàng thực tế / Tải trọng tối đa cho phép) × 100%.
Đơn vị: %
Phạm vi: Vận tải đường bộ, đường biển, hàng lẻ
Nguồn: CSCMP – Logistics Glossary 

cscmp.org
