insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG026','OTIF (On-Time In-Full) · Giao hàng đầy đủ và đúng hạn','Lĩnh vực: Vận tải
Chủ đề: Giao hàng đầy đủ và đúng hạn
Thuật ngữ: OTIF (On-Time In-Full)
Định nghĩa: Chỉ số đo tỷ lệ đơn hàng được giao đúng thời gian cam kết và đầy đủ số lượng theo yêu cầu khách hàng.
Ví dụ thực tế: Có 100 đơn hàng đến hạn, trong đó 85 đơn được giao đúng giờ và đủ số lượng. OTIF là 85%.
Cách tính KPI: OTIF = (Số đơn giao đúng hạn và đủ số lượng / Tổng số đơn đến hạn) × 100%.
Đơn vị: %
Phạm vi: Vận tải, phân phối, quản lý đơn hàng
Nguồn: DHL – Logistics KPIs; tài liệu Logistics and Distribution Management 

