insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG027','Load Factor · Tỷ lệ sử dụng tải trọng','Lĩnh vực: Vận tải
Chủ đề: Tỷ lệ sử dụng tải trọng
Thuật ngữ: Load Factor
Định nghĩa: Tỷ lệ giữa khối lượng hàng hóa thực tế được vận chuyển và tải trọng hàng hóa tối đa cho phép của phương tiện.
Ví dụ thực tế: Xe tải có tải trọng cho phép 10 tấn, thực tế chở 8 tấn. Load Factor là 80%.
Cách tính KPI: Load Factor = (Khối lượng hàng thực tế / Tải trọng hàng hóa cho phép) × 100%.
Đơn vị: %
Phạm vi: Vận tải đường bộ, đường sắt, đường biển
Nguồn: GHG Protocol – Scope 3 Calculation Guidance 

