insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG028','Empty Running Rate · Tỷ lệ chạy xe rỗng','Lĩnh vực: Vận tải
Chủ đề: Tỷ lệ chạy xe rỗng
Thuật ngữ: Empty Running Rate
Định nghĩa: Tỷ lệ quãng đường phương tiện di chuyển không chở hàng trên tổng quãng đường phương tiện thực hiện.
Ví dụ thực tế: Xe chạy tổng cộng 10.000 km trong tháng, trong đó 2.500 km không chở hàng.
Cách tính KPI: Empty Running Rate = (Số km chạy rỗng / Tổng số km phương tiện chạy) × 100%.
Đơn vị: %
Phạm vi: Vận tải đường bộ, quản lý đội xe
Nguồn: GHG Protocol – Scope 3 Calculation Guidance (dữ liệu hoạt động vận tải) 

