insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG029','Cost per Shipment · Chi phí vận chuyển trên mỗi lô hàng','Lĩnh vực: Vận tải
Chủ đề: Chi phí vận chuyển trên mỗi lô hàng
Thuật ngữ: Cost per Shipment
Định nghĩa: Chi phí logistics bình quân để thực hiện một lô hàng trong một khoảng thời gian xác định.
Ví dụ thực tế: Doanh nghiệp chi 150 triệu đồng cho 500 lô hàng trong tháng. Chi phí bình quân là 300.000 đồng/lô.
Cách tính KPI: Cost per Shipment = Tổng chi phí logistics thuộc phạm vi đo / Tổng số lô hàng hoàn thành.
Đơn vị: VNĐ/lô hàng
Phạm vi: Vận tải, giao nhận, phân phối
Nguồn: DHL – Logistics KPIs 

DHL
