insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('LOG030','Inventory Accuracy · Độ chính xác tồn kho','Lĩnh vực: Kho bãi
Chủ đề: Độ chính xác tồn kho
Thuật ngữ: Inventory Accuracy
Định nghĩa: Mức độ khớp nhau giữa số lượng tồn kho thực tế và số lượng được ghi nhận trên hệ thống quản lý kho.
Ví dụ thực tế: Hệ thống ghi nhận 1.000 sản phẩm, kiểm kê thực tế cũng có 1.000 sản phẩm và không có sai lệch.
Cách tính KPI: Inventory Record Accuracy = (Số bản ghi SKU-vị trí khớp với thực tế theo ngưỡng sai lệch quy định / Tổng số bản ghi được kiểm kê) × 100%.
Đơn vị: %
Phạm vi: Quản lý tồn kho, kho hàng
Nguồn: ASEAN – Process in Warehousing; DHL – Logistics KPIs 

ASEAN Main Portal+1
