insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC001','TMS · Phần mềm quản lý vận tải','Công nghệ: TMS
Nhóm: Phần mềm quản lý vận tải
Chức năng: Lập kế hoạch chuyến; điều phối xe/tài xế; tối ưu tuyến; theo dõi vận chuyển; quản lý cước và chứng từ tùy hệ thống.
Vấn đề giải quyết: Thiếu khả năng quan sát chuyến; điều phối thủ công; tỷ lệ xe chạy rỗng hoặc giao trễ cao.
Ứng dụng logistics: Lập kế hoạch tuyến, ghép đơn, phân xe, theo dõi GPS, cảnh báo chậm và đối soát cước.
Điều kiện triển khai: Có quy trình vận tải tương đối chuẩn; dữ liệu đơn/điểm giao/xe/tài xế; bản đồ và GPS nếu cần; nhân sự vận hành; khả năng tích hợp.
Dữ liệu cần có: Đơn hàng; điểm lấy-giao; khung giờ; tải trọng; phương tiện; chi phí; trạng thái chuyến.
Lợi ích: Tăng khả năng theo dõi, chuẩn hóa điều phối; tiềm năng giảm km rỗng và chi phí nếu tối ưu tốt.
Hạn chế/rủi ro: Chất lượng dữ liệu địa chỉ và thời gian; chi phí triển khai/tích hợp; phụ thuộc bản đồ/GPS; không bảo đảm tự động giảm chi phí.
Nguồn: CSCMP logistics activities: https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx; UNCTAD digital transport: https://unctad.org/publication/review-maritime-transport-2024
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Cong_nghe_CDS',false,'https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx','["https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx", "https://unctad.org/publication/review-maritime-transport-2024"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 4}, "fields": {"ID": "TEC001", "Công nghệ": "TMS", "Nhóm": "Phần mềm quản lý vận tải", "Chức năng": "Lập kế hoạch chuyến; điều phối xe/tài xế; tối ưu tuyến; theo dõi vận chuyển; quản lý cước và chứng từ tùy hệ thống.", "Vấn đề giải quyết": "Thiếu khả năng quan sát chuyến; điều phối thủ công; tỷ lệ xe chạy rỗng hoặc giao trễ cao.", "Ứng dụng logistics": "Lập kế hoạch tuyến, ghép đơn, phân xe, theo dõi GPS, cảnh báo chậm và đối soát cước.", "Điều kiện triển khai": "Có quy trình vận tải tương đối chuẩn; dữ liệu đơn/điểm giao/xe/tài xế; bản đồ và GPS nếu cần; nhân sự vận hành; khả năng tích hợp.", "Dữ liệu cần có": "Đơn hàng; điểm lấy-giao; khung giờ; tải trọng; phương tiện; chi phí; trạng thái chuyến.", "Lợi ích": "Tăng khả năng theo dõi, chuẩn hóa điều phối; tiềm năng giảm km rỗng và chi phí nếu tối ưu tốt.", "Hạn chế/rủi ro": "Chất lượng dữ liệu địa chỉ và thời gian; chi phí triển khai/tích hợp; phụ thuộc bản đồ/GPS; không bảo đảm tự động giảm chi phí.", "Nguồn": "CSCMP logistics activities: https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx; UNCTAD digital transport: https://unctad.org/publication/review-maritime-transport-2024", "Người duyệt": "Chuyên gia công nghệ", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC002','WMS · Phần mềm quản lý kho','Công nghệ: WMS
Nhóm: Phần mềm quản lý kho
Chức năng: Quản lý nhận hàng, put-away, vị trí lưu trữ, bổ sung, picking, packing, xuất kho, kiểm kê và tồn kho theo thời gian gần thực.
Vấn đề giải quyết: Sai lệch tồn kho; tìm hàng lâu; nhầm lẫn picking; thiếu khả năng kiểm soát vị trí.
Ứng dụng logistics: Quét mã vạch/RFID khi nhập-xuất; gợi ý vị trí; phân công picking; kiểm kê chu kỳ.
Điều kiện triển khai: Cần chuẩn hóa sơ đồ kho, mã hàng và quy trình nhập – xuất – lưu trữ; có dữ liệu tồn kho chính xác, thiết bị quét mã và khả năng kết nối với các hệ thống liên quan.
Dữ liệu cần có: Sơ đồ kho và mã vị trí; danh mục SKU/đơn vị tính; quy trình chuẩn; thiết bị quét/mạng; dữ liệu tồn đầu kỳ.
Lợi ích: Tăng khả năng chính xác tồn kho và truy vết thao tác; cải thiện tốc độ xử lý nếu quy trình và dữ liệu tốt.
Hạn chế/rủi ro: Cần chuẩn hóa mã hàng/vị trí; thay đổi thói quen nhân viên; chi phí thiết bị; tích hợp ERP/TMS.
Nguồn: CSCMP logistics activities: https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Cong_nghe_CDS',false,'https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx','["https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 5}, "fields": {"ID": "TEC002", "Công nghệ": "WMS", "Nhóm": "Phần mềm quản lý kho", "Chức năng": "Quản lý nhận hàng, put-away, vị trí lưu trữ, bổ sung, picking, packing, xuất kho, kiểm kê và tồn kho theo thời gian gần thực.", "Vấn đề giải quyết": "Sai lệch tồn kho; tìm hàng lâu; nhầm lẫn picking; thiếu khả năng kiểm soát vị trí.", "Ứng dụng logistics": "Quét mã vạch/RFID khi nhập-xuất; gợi ý vị trí; phân công picking; kiểm kê chu kỳ.", "Điều kiện triển khai": "Cần chuẩn hóa sơ đồ kho, mã hàng và quy trình nhập – xuất – lưu trữ; có dữ liệu tồn kho chính xác, thiết bị quét mã và khả năng kết nối với các hệ thống liên quan.", "Dữ liệu cần có": "Sơ đồ kho và mã vị trí; danh mục SKU/đơn vị tính; quy trình chuẩn; thiết bị quét/mạng; dữ liệu tồn đầu kỳ.", "Lợi ích": "Tăng khả năng chính xác tồn kho và truy vết thao tác; cải thiện tốc độ xử lý nếu quy trình và dữ liệu tốt.", "Hạn chế/rủi ro": "Cần chuẩn hóa mã hàng/vị trí; thay đổi thói quen nhân viên; chi phí thiết bị; tích hợp ERP/TMS.", "Nguồn": "CSCMP logistics activities: https://cscmp.org/CSCMP/cscmp/educate/scm_definitions_and_glossary_of_terms.aspx", "Người duyệt": "Chuyên gia kho vận", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC003','ERP · Phần mềm hoạch định nguồn lực','Công nghệ: ERP
Nhóm: Phần mềm hoạch định nguồn lực
Chức năng: Tích hợp các quy trình và dữ liệu cốt lõi như tài chính, mua hàng, bán hàng, tồn kho, sản xuất và nhân sự theo module.
Vấn đề giải quyết: Dữ liệu phân tán giữa phòng ban; nhập liệu lặp; thiếu báo cáo quản trị thống nhất.
Ứng dụng logistics: Liên kết đơn hàng, mua hàng, tồn kho, hóa đơn và kế toán; đồng bộ dữ liệu giữa bộ phận.
Điều kiện triển khai: Cần chuẩn hóa quy trình giữa các phòng ban, dữ liệu dùng chung và xác định rõ các phân hệ cần triển khai; có ngân sách, nhân sự phụ trách và kế hoạch đào tạo.
Dữ liệu cần có: Bản đồ quy trình; chủ sở hữu dữ liệu; danh mục chuẩn; yêu cầu phân quyền; kế hoạch chuyển đổi dữ liệu và quản trị thay đổi.
Lợi ích: Tăng tính nhất quán dữ liệu và khả năng phối hợp liên phòng ban khi triển khai phù hợp.
Hạn chế/rủi ro: Dự án phức tạp; chi phí bản quyền/tùy biến; rủi ro triển khai kéo dài; không thay thế thiết kế quy trình.
Nguồn: OECD Digitalisation of SMEs: https://www.oecd.org/en/topics/digitalisation-of-smes.html
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Cong_nghe_CDS',false,'https://www.oecd.org/en/topics/digitalisation-of-smes.html','["https://www.oecd.org/en/topics/digitalisation-of-smes.html"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 6}, "fields": {"ID": "TEC003", "Công nghệ": "ERP", "Nhóm": "Phần mềm hoạch định nguồn lực", "Chức năng": "Tích hợp các quy trình và dữ liệu cốt lõi như tài chính, mua hàng, bán hàng, tồn kho, sản xuất và nhân sự theo module.", "Vấn đề giải quyết": "Dữ liệu phân tán giữa phòng ban; nhập liệu lặp; thiếu báo cáo quản trị thống nhất.", "Ứng dụng logistics": "Liên kết đơn hàng, mua hàng, tồn kho, hóa đơn và kế toán; đồng bộ dữ liệu giữa bộ phận.", "Điều kiện triển khai": "Cần chuẩn hóa quy trình giữa các phòng ban, dữ liệu dùng chung và xác định rõ các phân hệ cần triển khai; có ngân sách, nhân sự phụ trách và kế hoạch đào tạo.", "Dữ liệu cần có": "Bản đồ quy trình; chủ sở hữu dữ liệu; danh mục chuẩn; yêu cầu phân quyền; kế hoạch chuyển đổi dữ liệu và quản trị thay đổi.", "Lợi ích": "Tăng tính nhất quán dữ liệu và khả năng phối hợp liên phòng ban khi triển khai phù hợp.", "Hạn chế/rủi ro": "Dự án phức tạp; chi phí bản quyền/tùy biến; rủi ro triển khai kéo dài; không thay thế thiết kế quy trình.", "Nguồn": "OECD Digitalisation of SMEs: https://www.oecd.org/en/topics/digitalisation-of-smes.html", "Người duyệt": "Chuyên gia ERP", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC004','AI · Dự báo nhu cầu','Công nghệ: AI
Nhóm: Dự báo nhu cầu
Chức năng: Dùng mô hình thống kê hoặc học máy để ước tính nhu cầu tương lai từ dữ liệu lịch sử và yếu tố liên quan.
Vấn đề giải quyết: Dự báo thủ công thiếu nhất quán; tồn kho dư hoặc thiếu; khó nhận diện biến động.
Ứng dụng logistics: Dự báo lượng đơn, nhu cầu SKU theo khu vực/mùa vụ; hỗ trợ lập kế hoạch tồn kho và năng lực vận tải.
Điều kiện triển khai: Cần dữ liệu lịch sử về đơn hàng, doanh số và nhu cầu đủ đầy đủ, chính xác; có nhân sự quản lý dữ liệu và khả năng kiểm tra, cập nhật mô hình dự báo định kỳ.
Dữ liệu cần có: Dữ liệu lịch sử đủ dài và nhất quán; lịch khuyến mại/mùa vụ; xử lý hàng thiếu; quy trình rà soát dự báo; người chịu trách nhiệm.
Lợi ích: Hỗ trợ lập kế hoạch dựa trên dữ liệu; có thể giảm sai số nếu dữ liệu và mô hình phù hợp.
Hạn chế/rủi ro: Không dự báo chắc chắn; biến cố bất thường làm giảm độ chính xác; cần giám sát drift và đánh giá định kỳ.
Nguồn: NIST AI RMF: https://www.nist.gov/itl/ai-risk-management-framework
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Cong_nghe_CDS',false,'https://www.nist.gov/itl/ai-risk-management-framework','["https://www.nist.gov/itl/ai-risk-management-framework"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 7}, "fields": {"ID": "TEC004", "Công nghệ": "AI", "Nhóm": "Dự báo nhu cầu", "Chức năng": "Dùng mô hình thống kê hoặc học máy để ước tính nhu cầu tương lai từ dữ liệu lịch sử và yếu tố liên quan.", "Vấn đề giải quyết": "Dự báo thủ công thiếu nhất quán; tồn kho dư hoặc thiếu; khó nhận diện biến động.", "Ứng dụng logistics": "Dự báo lượng đơn, nhu cầu SKU theo khu vực/mùa vụ; hỗ trợ lập kế hoạch tồn kho và năng lực vận tải.", "Điều kiện triển khai": "Cần dữ liệu lịch sử về đơn hàng, doanh số và nhu cầu đủ đầy đủ, chính xác; có nhân sự quản lý dữ liệu và khả năng kiểm tra, cập nhật mô hình dự báo định kỳ.", "Dữ liệu cần có": "Dữ liệu lịch sử đủ dài và nhất quán; lịch khuyến mại/mùa vụ; xử lý hàng thiếu; quy trình rà soát dự báo; người chịu trách nhiệm.", "Lợi ích": "Hỗ trợ lập kế hoạch dựa trên dữ liệu; có thể giảm sai số nếu dữ liệu và mô hình phù hợp.", "Hạn chế/rủi ro": "Không dự báo chắc chắn; biến cố bất thường làm giảm độ chính xác; cần giám sát drift và đánh giá định kỳ.", "Nguồn": "NIST AI RMF: https://www.nist.gov/itl/ai-risk-management-framework", "Người duyệt": "Chuyên gia dữ liệu/AI", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC005','ML · Tối ưu tuyến bằng AI','Công nghệ: ML
Nhóm: Tối ưu tuyến bằng AI
Chức năng: Thuật toán tối ưu hóa hoặc mô hình hỗ trợ chọn tuyến/lịch trình theo ràng buộc vận hành.
Vấn đề giải quyết: Điều phối tuyến thủ công; quãng đường dài; giao trễ; sử dụng xe chưa hiệu quả.
Ứng dụng logistics: Đề xuất tuyến theo điểm giao, khung giờ, tải trọng, thời gian lái xe và điều kiện đường.
Điều kiện triển khai: Cần dữ liệu chính xác về địa chỉ giao hàng, phương tiện, tải trọng, thời gian và điều kiện giao nhận; có hệ thống cập nhật thông tin giao thông và nhân sự giám sát điều phối.
Dữ liệu cần có: Địa chỉ geocode; thời gian dịch vụ; năng lực xe; ràng buộc pháp lý; dữ liệu giao thông; mục tiêu tối ưu rõ ràng.
Lợi ích: Hỗ trợ giảm thời gian/quãng đường và tăng số điểm phục vụ trong một số bối cảnh.
Hạn chế/rủi ro: Kết quả phụ thuộc dữ liệu giao thông và ràng buộc; người điều phối cần xử lý ngoại lệ; không bảo đảm tối ưu toàn cục trong thực tế.
Nguồn: NIST AI RMF: https://www.nist.gov/itl/ai-risk-management-framework; UNCTAD: https://unctad.org/publication/review-maritime-transport-2024
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Cong_nghe_CDS',false,'https://www.nist.gov/itl/ai-risk-management-framework','["https://www.nist.gov/itl/ai-risk-management-framework", "https://unctad.org/publication/review-maritime-transport-2024"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 8}, "fields": {"ID": "TEC005", "Công nghệ": "ML", "Nhóm": "Tối ưu tuyến bằng AI", "Chức năng": "Thuật toán tối ưu hóa hoặc mô hình hỗ trợ chọn tuyến/lịch trình theo ràng buộc vận hành.", "Vấn đề giải quyết": "Điều phối tuyến thủ công; quãng đường dài; giao trễ; sử dụng xe chưa hiệu quả.", "Ứng dụng logistics": "Đề xuất tuyến theo điểm giao, khung giờ, tải trọng, thời gian lái xe và điều kiện đường.", "Điều kiện triển khai": "Cần dữ liệu chính xác về địa chỉ giao hàng, phương tiện, tải trọng, thời gian và điều kiện giao nhận; có hệ thống cập nhật thông tin giao thông và nhân sự giám sát điều phối.", "Dữ liệu cần có": "Địa chỉ geocode; thời gian dịch vụ; năng lực xe; ràng buộc pháp lý; dữ liệu giao thông; mục tiêu tối ưu rõ ràng.", "Lợi ích": "Hỗ trợ giảm thời gian/quãng đường và tăng số điểm phục vụ trong một số bối cảnh.", "Hạn chế/rủi ro": "Kết quả phụ thuộc dữ liệu giao thông và ràng buộc; người điều phối cần xử lý ngoại lệ; không bảo đảm tối ưu toàn cục trong thực tế.", "Nguồn": "NIST AI RMF: https://www.nist.gov/itl/ai-risk-management-framework; UNCTAD: https://unctad.org/publication/review-maritime-transport-2024", "Người duyệt": "Chuyên gia vận tải số", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC006','IoT · Internet vạn vật trong logistics','Công nghệ: IoT
Nhóm: Internet vạn vật trong logistics
Chức năng: Mạng thiết bị/cảm biến kết nối để thu thập và truyền dữ liệu về vị trí, trạng thái hoặc điều kiện vận hành.
Vấn đề giải quyết: Thiếu dữ liệu thời gian thực về vị trí, nhiệt độ, độ ẩm, rung lắc hoặc tình trạng thiết bị.
Ứng dụng logistics: Cảm biến nhiệt độ container lạnh; GPS xe; cảm biến cửa kho; theo dõi tài sản.
Điều kiện triển khai: Cần xác định mục tiêu giám sát, lựa chọn cảm biến phù hợp, đảm bảo nguồn điện và kết nối mạng; có hệ thống tiếp nhận dữ liệu và quy trình xử lý cảnh báo.
Dữ liệu cần có: Thiết bị phù hợp; kết nối mạng; nền tảng nhận dữ liệu; hiệu chuẩn cảm biến; quy trình xử lý cảnh báo.
Lợi ích: Tăng khả năng giám sát và phát hiện bất thường; hỗ trợ truy xuất điều kiện vận chuyển.
Hạn chế/rủi ro: Chi phí thiết bị/kết nối; vùng mất sóng; pin; an ninh mạng; dữ liệu cảm biến cần kiểm định.
Nguồn: GS1 EPCIS hỗ trợ sự kiện và trạng thái như nhiệt độ/tác động: https://support.gs1.org/support/solutions/articles/43000755325-what-is-electronic-product-code-information-services-epcis-
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Cong_nghe_CDS',false,'https://support.gs1.org/support/solutions/articles/43000755325-what-is-electronic-product-code-information-services-epcis-','["https://support.gs1.org/support/solutions/articles/43000755325-what-is-electronic-product-code-information-services-epcis-"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 9}, "fields": {"ID": "TEC006", "Công nghệ": "IoT", "Nhóm": "Internet vạn vật trong logistics", "Chức năng": "Mạng thiết bị/cảm biến kết nối để thu thập và truyền dữ liệu về vị trí, trạng thái hoặc điều kiện vận hành.", "Vấn đề giải quyết": "Thiếu dữ liệu thời gian thực về vị trí, nhiệt độ, độ ẩm, rung lắc hoặc tình trạng thiết bị.", "Ứng dụng logistics": "Cảm biến nhiệt độ container lạnh; GPS xe; cảm biến cửa kho; theo dõi tài sản.", "Điều kiện triển khai": "Cần xác định mục tiêu giám sát, lựa chọn cảm biến phù hợp, đảm bảo nguồn điện và kết nối mạng; có hệ thống tiếp nhận dữ liệu và quy trình xử lý cảnh báo.", "Dữ liệu cần có": "Thiết bị phù hợp; kết nối mạng; nền tảng nhận dữ liệu; hiệu chuẩn cảm biến; quy trình xử lý cảnh báo.", "Lợi ích": "Tăng khả năng giám sát và phát hiện bất thường; hỗ trợ truy xuất điều kiện vận chuyển.", "Hạn chế/rủi ro": "Chi phí thiết bị/kết nối; vùng mất sóng; pin; an ninh mạng; dữ liệu cảm biến cần kiểm định.", "Nguồn": "GS1 EPCIS hỗ trợ sự kiện và trạng thái như nhiệt độ/tác động: https://support.gs1.org/support/solutions/articles/43000755325-what-is-electronic-product-code-information-services-epcis-", "Người duyệt": "Chuyên gia IoT", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC007','Blockchain · Sổ cái phân tán','Công nghệ: Blockchain
Nhóm: Sổ cái phân tán
Chức năng: Cơ chế ghi nhận giao dịch/sự kiện trên mạng nhiều nút theo quy tắc đồng thuận; dữ liệu đã ghi có thể khó sửa đổi tùy thiết kế.
Vấn đề giải quyết: Các bên thiếu niềm tin hoặc khó đối chiếu lịch sử giao dịch và chứng từ.
Ứng dụng logistics: Chia sẻ dấu vết lô hàng/chứng từ giữa các bên; có thể kết hợp chuẩn định danh và truy xuất.
Điều kiện triển khai: Cần có nhiều bên tham gia chia sẻ dữ liệu, thống nhất quy trình và quyền truy cập; đảm bảo dữ liệu đầu vào được xác thực, có khả năng tích hợp và nhân sự vận hành hệ thống.
Dữ liệu cần có: Nhiều bên cùng tham gia; quy tắc quản trị; quyền truy cập; chuẩn dữ liệu; xác định vấn đề cần giải quyết.
Lợi ích: Có thể tăng khả năng kiểm tra lịch sử và chia sẻ dữ liệu trong hệ sinh thái phù hợp.
Hạn chế/rủi ro: Không bảo đảm dữ liệu đầu vào đúng; vấn đề quyền riêng tư, hiệu năng, chi phí, quản trị và pháp lý; không phải trường hợp nào cũng cần blockchain.
Nguồn: UNCTAD Review of Maritime Transport 2024: https://unctad.org/publication/review-maritime-transport-2024
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Cong_nghe_CDS',false,'https://unctad.org/publication/review-maritime-transport-2024','["https://unctad.org/publication/review-maritime-transport-2024"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 10}, "fields": {"ID": "TEC007", "Công nghệ": "Blockchain", "Nhóm": "Sổ cái phân tán", "Chức năng": "Cơ chế ghi nhận giao dịch/sự kiện trên mạng nhiều nút theo quy tắc đồng thuận; dữ liệu đã ghi có thể khó sửa đổi tùy thiết kế.", "Vấn đề giải quyết": "Các bên thiếu niềm tin hoặc khó đối chiếu lịch sử giao dịch và chứng từ.", "Ứng dụng logistics": "Chia sẻ dấu vết lô hàng/chứng từ giữa các bên; có thể kết hợp chuẩn định danh và truy xuất.", "Điều kiện triển khai": "Cần có nhiều bên tham gia chia sẻ dữ liệu, thống nhất quy trình và quyền truy cập; đảm bảo dữ liệu đầu vào được xác thực, có khả năng tích hợp và nhân sự vận hành hệ thống.", "Dữ liệu cần có": "Nhiều bên cùng tham gia; quy tắc quản trị; quyền truy cập; chuẩn dữ liệu; xác định vấn đề cần giải quyết.", "Lợi ích": "Có thể tăng khả năng kiểm tra lịch sử và chia sẻ dữ liệu trong hệ sinh thái phù hợp.", "Hạn chế/rủi ro": "Không bảo đảm dữ liệu đầu vào đúng; vấn đề quyền riêng tư, hiệu năng, chi phí, quản trị và pháp lý; không phải trường hợp nào cũng cần blockchain.", "Nguồn": "UNCTAD Review of Maritime Transport 2024: https://unctad.org/publication/review-maritime-transport-2024", "Người duyệt": "Chuyên gia công nghệ", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC008','Tích hợp dữ liệu · API (Application Programming Interface)','Công nghệ: Tích hợp dữ liệu
Nhóm: API (Application Programming Interface)
Chức năng: Giao diện/lớp quy tắc cho phép các hệ thống trao đổi dữ liệu và yêu cầu chức năng với nhau.
Vấn đề giải quyết: Nhập liệu lặp giữa ERP, WMS, TMS; dữ liệu cập nhật chậm hoặc không đồng bộ.
Ứng dụng logistics: Đồng bộ đơn hàng từ ERP sang WMS, trạng thái giao hàng từ TMS về hệ thống bán hàng.
Điều kiện triển khai: Cần các hệ thống có khả năng hỗ trợ API, dữ liệu được chuẩn hóa và có tài liệu kỹ thuật; thiết lập cơ chế bảo mật, phân quyền và kiểm tra kết nối.
Dữ liệu cần có: Tài liệu API; xác thực và phân quyền; mapping dữ liệu; giới hạn tốc độ; môi trường thử nghiệm; giám sát lỗi.
Lợi ích: Giảm thao tác nhập lại; hỗ trợ luồng dữ liệu xuyên hệ thống.
Hạn chế/rủi ro: API không tự bảo đảm dữ liệu đúng; cần quản lý phiên bản, bảo mật, xử lý lỗi và thỏa thuận nhà cung cấp.
Nguồn: NIST AI RMF (quản trị hệ thống/rủi ro công nghệ): https://www.nist.gov/itl/ai-risk-management-framework
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Cong_nghe_CDS',false,'https://www.nist.gov/itl/ai-risk-management-framework','["https://www.nist.gov/itl/ai-risk-management-framework"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 11}, "fields": {"ID": "TEC008", "Công nghệ": "Tích hợp dữ liệu", "Nhóm": "API (Application Programming Interface)", "Chức năng": "Giao diện/lớp quy tắc cho phép các hệ thống trao đổi dữ liệu và yêu cầu chức năng với nhau.", "Vấn đề giải quyết": "Nhập liệu lặp giữa ERP, WMS, TMS; dữ liệu cập nhật chậm hoặc không đồng bộ.", "Ứng dụng logistics": "Đồng bộ đơn hàng từ ERP sang WMS, trạng thái giao hàng từ TMS về hệ thống bán hàng.", "Điều kiện triển khai": "Cần các hệ thống có khả năng hỗ trợ API, dữ liệu được chuẩn hóa và có tài liệu kỹ thuật; thiết lập cơ chế bảo mật, phân quyền và kiểm tra kết nối.", "Dữ liệu cần có": "Tài liệu API; xác thực và phân quyền; mapping dữ liệu; giới hạn tốc độ; môi trường thử nghiệm; giám sát lỗi.", "Lợi ích": "Giảm thao tác nhập lại; hỗ trợ luồng dữ liệu xuyên hệ thống.", "Hạn chế/rủi ro": "API không tự bảo đảm dữ liệu đúng; cần quản lý phiên bản, bảo mật, xử lý lỗi và thỏa thuận nhà cung cấp.", "Nguồn": "NIST AI RMF (quản trị hệ thống/rủi ro công nghệ): https://www.nist.gov/itl/ai-risk-management-framework", "Người duyệt": "Kiến trúc sư hệ thống", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC009','Nhận dạng tự động · Mã vạch và QR','Công nghệ: Nhận dạng tự động
Nhóm: Mã vạch và QR
Chức năng: Phương tiện mã hóa dữ liệu để thiết bị đọc nhận dạng đối tượng; loại mã và dữ liệu phụ thuộc tiêu chuẩn áp dụng.
Vấn đề giải quyết: Nhập liệu thủ công; khó nhận dạng nhanh sản phẩm, kiện hàng hoặc vị trí.
Ứng dụng logistics: Quét mã sản phẩm, pallet, vị trí kho, vận đơn hoặc chứng từ.
Điều kiện triển khai: Cần chuẩn hóa mã định danh hàng hóa, lựa chọn loại mã phù hợp; trang bị máy in, thiết bị quét và tích hợp dữ liệu với hệ thống quản lý kho hoặc ERP.
Dữ liệu cần có: Chuẩn mã định danh; máy in/đầu đọc; chất lượng nhãn; quy trình cấp mã; hệ thống lưu dữ liệu.
Lợi ích: Tăng tốc độ ghi nhận và giảm lỗi nhập liệu thủ công khi triển khai đúng.
Hạn chế/rủi ro: Mã không tự tạo khả năng truy xuất nếu không có hệ thống sự kiện/dữ liệu liên kết; nhãn hỏng hoặc mã trùng gây lỗi.
Nguồn: GS1 EPCIS/GS1 standards: https://support.gs1.org/support/solutions/articles/43000755325-what-is-electronic-product-code-information-services-epcis-
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Cong_nghe_CDS',false,'https://support.gs1.org/support/solutions/articles/43000755325-what-is-electronic-product-code-information-services-epcis-','["https://support.gs1.org/support/solutions/articles/43000755325-what-is-electronic-product-code-information-services-epcis-"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 12}, "fields": {"ID": "TEC009", "Công nghệ": "Nhận dạng tự động", "Nhóm": "Mã vạch và QR", "Chức năng": "Phương tiện mã hóa dữ liệu để thiết bị đọc nhận dạng đối tượng; loại mã và dữ liệu phụ thuộc tiêu chuẩn áp dụng.", "Vấn đề giải quyết": "Nhập liệu thủ công; khó nhận dạng nhanh sản phẩm, kiện hàng hoặc vị trí.", "Ứng dụng logistics": "Quét mã sản phẩm, pallet, vị trí kho, vận đơn hoặc chứng từ.", "Điều kiện triển khai": "Cần chuẩn hóa mã định danh hàng hóa, lựa chọn loại mã phù hợp; trang bị máy in, thiết bị quét và tích hợp dữ liệu với hệ thống quản lý kho hoặc ERP.", "Dữ liệu cần có": "Chuẩn mã định danh; máy in/đầu đọc; chất lượng nhãn; quy trình cấp mã; hệ thống lưu dữ liệu.", "Lợi ích": "Tăng tốc độ ghi nhận và giảm lỗi nhập liệu thủ công khi triển khai đúng.", "Hạn chế/rủi ro": "Mã không tự tạo khả năng truy xuất nếu không có hệ thống sự kiện/dữ liệu liên kết; nhãn hỏng hoặc mã trùng gây lỗi.", "Nguồn": "GS1 EPCIS/GS1 standards: https://support.gs1.org/support/solutions/articles/43000755325-what-is-electronic-product-code-information-services-epcis-", "Người duyệt": "Chuyên gia tự động hóa", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC010','Nhận dạng tự động · RFID','Công nghệ: Nhận dạng tự động
Nhóm: RFID
Chức năng: Công nghệ nhận dạng bằng sóng vô tuyến giữa thẻ và đầu đọc; không nhất thiết yêu cầu quét trực tiếp từng mã như barcode.
Vấn đề giải quyết: Kiểm kê chậm; khó ghi nhận nhiều đối tượng trong thời gian ngắn hoặc qua luồng di chuyển.
Ứng dụng logistics: Ghi nhận pallet/thùng hàng qua cổng đọc; kiểm kê tài sản và hàng hóa.
Điều kiện triển khai: Cần lựa chọn thẻ RFID và đầu đọc phù hợp, khảo sát môi trường sử dụng và vị trí lắp đặt; chuẩn hóa mã định danh, tích hợp hệ thống và kiểm tra khả năng nhận diện.
Dữ liệu cần có: Phân tích môi trường RF; loại thẻ/đầu đọc; vị trí anten; mã định danh; tích hợp WMS/ERP.
Lợi ích: Có thể tăng tốc độ thu thập dữ liệu và tự động hóa điểm kiểm soát.
Hạn chế/rủi ro: Chi phí thẻ/đầu đọc; nhiễu kim loại/chất lỏng; cần thử nghiệm tại môi trường thật; không phải hàng hóa nào cũng phù hợp.
Nguồn: GS1 EPCIS data-carrier neutral, hỗ trợ barcode và RAIN RFID: https://support.gs1.org/support/solutions/articles/43000755325-what-is-electronic-product-code-information-services-epcis-
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Cong_nghe_CDS',false,'https://support.gs1.org/support/solutions/articles/43000755325-what-is-electronic-product-code-information-services-epcis-','["https://support.gs1.org/support/solutions/articles/43000755325-what-is-electronic-product-code-information-services-epcis-"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 13}, "fields": {"ID": "TEC010", "Công nghệ": "Nhận dạng tự động", "Nhóm": "RFID", "Chức năng": "Công nghệ nhận dạng bằng sóng vô tuyến giữa thẻ và đầu đọc; không nhất thiết yêu cầu quét trực tiếp từng mã như barcode.", "Vấn đề giải quyết": "Kiểm kê chậm; khó ghi nhận nhiều đối tượng trong thời gian ngắn hoặc qua luồng di chuyển.", "Ứng dụng logistics": "Ghi nhận pallet/thùng hàng qua cổng đọc; kiểm kê tài sản và hàng hóa.", "Điều kiện triển khai": "Cần lựa chọn thẻ RFID và đầu đọc phù hợp, khảo sát môi trường sử dụng và vị trí lắp đặt; chuẩn hóa mã định danh, tích hợp hệ thống và kiểm tra khả năng nhận diện.", "Dữ liệu cần có": "Phân tích môi trường RF; loại thẻ/đầu đọc; vị trí anten; mã định danh; tích hợp WMS/ERP.", "Lợi ích": "Có thể tăng tốc độ thu thập dữ liệu và tự động hóa điểm kiểm soát.", "Hạn chế/rủi ro": "Chi phí thẻ/đầu đọc; nhiễu kim loại/chất lỏng; cần thử nghiệm tại môi trường thật; không phải hàng hóa nào cũng phù hợp.", "Nguồn": "GS1 EPCIS data-carrier neutral, hỗ trợ barcode và RAIN RFID: https://support.gs1.org/support/solutions/articles/43000755325-what-is-electronic-product-code-information-services-epcis-", "Người duyệt": "Chuyên gia tự động hóa", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC011','Điện toán đám mây · Cloud computing','Công nghệ: Điện toán đám mây
Nhóm: Cloud computing
Chức năng: Cung cấp tài nguyên CNTT như máy chủ, lưu trữ, cơ sở dữ liệu và phần mềm qua mạng theo mô hình dịch vụ.
Vấn đề giải quyết: Hạ tầng tại chỗ khó mở rộng; chi phí đầu tư ban đầu cao; truy cập hệ thống phân tán.
Ứng dụng logistics: Triển khai WMS/TMS/ERP dạng cloud; chia sẻ dữ liệu giữa chi nhánh.
Điều kiện triển khai: Cần có kết nối Internet ổn định, lựa chọn nhà cung cấp cloud phù hợp; xác định nhu cầu lưu trữ, bảo mật, sao lưu và phương án khôi phục dữ liệu.
Dữ liệu cần có: Kết nối mạng; phân loại dữ liệu; đánh giá nhà cung cấp; sao lưu; phân quyền; yêu cầu lưu trú dữ liệu và tuân thủ.
Lợi ích: Linh hoạt mở rộng và giảm nhu cầu tự vận hành một phần hạ tầng.
Hạn chế/rủi ro: Phụ thuộc kết nối/nhà cung cấp; chi phí định kỳ; rủi ro cấu hình bảo mật và khóa nhà cung cấp.
Nguồn: OECD Digitalisation of SMEs: https://www.oecd.org/en/topics/digitalisation-of-smes.html
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Cong_nghe_CDS',false,'https://www.oecd.org/en/topics/digitalisation-of-smes.html','["https://www.oecd.org/en/topics/digitalisation-of-smes.html"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 14}, "fields": {"ID": "TEC011", "Công nghệ": "Điện toán đám mây", "Nhóm": "Cloud computing", "Chức năng": "Cung cấp tài nguyên CNTT như máy chủ, lưu trữ, cơ sở dữ liệu và phần mềm qua mạng theo mô hình dịch vụ.", "Vấn đề giải quyết": "Hạ tầng tại chỗ khó mở rộng; chi phí đầu tư ban đầu cao; truy cập hệ thống phân tán.", "Ứng dụng logistics": "Triển khai WMS/TMS/ERP dạng cloud; chia sẻ dữ liệu giữa chi nhánh.", "Điều kiện triển khai": "Cần có kết nối Internet ổn định, lựa chọn nhà cung cấp cloud phù hợp; xác định nhu cầu lưu trữ, bảo mật, sao lưu và phương án khôi phục dữ liệu.", "Dữ liệu cần có": "Kết nối mạng; phân loại dữ liệu; đánh giá nhà cung cấp; sao lưu; phân quyền; yêu cầu lưu trú dữ liệu và tuân thủ.", "Lợi ích": "Linh hoạt mở rộng và giảm nhu cầu tự vận hành một phần hạ tầng.", "Hạn chế/rủi ro": "Phụ thuộc kết nối/nhà cung cấp; chi phí định kỳ; rủi ro cấu hình bảo mật và khóa nhà cung cấp.", "Nguồn": "OECD Digitalisation of SMEs: https://www.oecd.org/en/topics/digitalisation-of-smes.html", "Người duyệt": "Chuyên gia hạ tầng", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC012','Phân tích dữ liệu · BI và dashboard','Công nghệ: Phân tích dữ liệu
Nhóm: BI và dashboard
Chức năng: Công cụ tổng hợp, trực quan hóa và phân tích dữ liệu để theo dõi hiệu quả và hỗ trợ quyết định.
Vấn đề giải quyết: Báo cáo thủ công; dữ liệu nhiều file; quản lý thiếu KPI nhất quán.
Ứng dụng logistics: Dashboard OTD, chi phí/chuyến, tồn kho, năng suất picking, tỷ lệ hàng hư hỏng.
Điều kiện triển khai: Cần xác định các KPI cần theo dõi, chuẩn hóa dữ liệu và công thức tính; đảm bảo khả năng kết nối nguồn dữ liệu, phân quyền và cập nhật báo cáo thường xuyên.
Dữ liệu cần có: Nguồn dữ liệu tin cậy; từ điển KPI; chủ sở hữu dữ liệu; lịch cập nhật; phân quyền.
Lợi ích: Tăng khả năng quan sát và phát hiện xu hướng; hỗ trợ quyết định kịp thời.
Hạn chế/rủi ro: Dashboard không tự sửa vấn đề dữ liệu; KPI định nghĩa sai dẫn đến quyết định sai; cần kiểm soát quyền truy cập.
Nguồn: ASCM SCOR metrics framework: https://scor.ascm.org/performance/introduction
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Cong_nghe_CDS',false,'https://scor.ascm.org/performance/introduction','["https://scor.ascm.org/performance/introduction"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 15}, "fields": {"ID": "TEC012", "Công nghệ": "Phân tích dữ liệu", "Nhóm": "BI và dashboard", "Chức năng": "Công cụ tổng hợp, trực quan hóa và phân tích dữ liệu để theo dõi hiệu quả và hỗ trợ quyết định.", "Vấn đề giải quyết": "Báo cáo thủ công; dữ liệu nhiều file; quản lý thiếu KPI nhất quán.", "Ứng dụng logistics": "Dashboard OTD, chi phí/chuyến, tồn kho, năng suất picking, tỷ lệ hàng hư hỏng.", "Điều kiện triển khai": "Cần xác định các KPI cần theo dõi, chuẩn hóa dữ liệu và công thức tính; đảm bảo khả năng kết nối nguồn dữ liệu, phân quyền và cập nhật báo cáo thường xuyên.", "Dữ liệu cần có": "Nguồn dữ liệu tin cậy; từ điển KPI; chủ sở hữu dữ liệu; lịch cập nhật; phân quyền.", "Lợi ích": "Tăng khả năng quan sát và phát hiện xu hướng; hỗ trợ quyết định kịp thời.", "Hạn chế/rủi ro": "Dashboard không tự sửa vấn đề dữ liệu; KPI định nghĩa sai dẫn đến quyết định sai; cần kiểm soát quyền truy cập.", "Nguồn": "ASCM SCOR metrics framework: https://scor.ascm.org/performance/introduction", "Người duyệt": "Chuyên gia dữ liệu", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC013','Tự động hóa kho · AGV/AMR','Công nghệ: Tự động hóa kho
Nhóm: AGV/AMR
Chức năng: AGV/AMR là phương tiện tự hành hỗ trợ vận chuyển hàng trong cơ sở; mức độ tự chủ và cách điều hướng tùy loại hệ thống.
Vấn đề giải quyết: Di chuyển nội bộ lặp lại; thiếu lao động; luồng di chuyển không hiệu quả.
Ứng dụng logistics: Vận chuyển pallet/thùng giữa khu nhận, lưu trữ, picking và đóng gói.
Điều kiện triển khai: Cần mặt bằng kho phù hợp, lối đi được bố trí rõ ràng, hạ tầng kết nối và trạm sạc; có hệ thống điều phối, quy trình an toàn và nhân sự bảo trì robot.
Dữ liệu cần có: Mặt bằng và luồng kho; tải trọng; an toàn người-máy; hệ thống điều phối; hạ tầng sạc và bảo trì.
Lợi ích: Có thể giảm thao tác di chuyển thủ công và cải thiện tính ổn định của luồng vật liệu.
Hạn chế/rủi ro: Đầu tư ban đầu và thay đổi layout; điểm nghẽn có thể chuyển vị trí; cần đánh giá ROI và an toàn.
Nguồn: UNCTAD Review of Maritime Transport 2024 (automation/digitalization port context): https://unctad.org/publication/review-maritime-transport-2024
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Cong_nghe_CDS',false,'https://unctad.org/publication/review-maritime-transport-2024','["https://unctad.org/publication/review-maritime-transport-2024"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 16}, "fields": {"ID": "TEC013", "Công nghệ": "Tự động hóa kho", "Nhóm": "AGV/AMR", "Chức năng": "AGV/AMR là phương tiện tự hành hỗ trợ vận chuyển hàng trong cơ sở; mức độ tự chủ và cách điều hướng tùy loại hệ thống.", "Vấn đề giải quyết": "Di chuyển nội bộ lặp lại; thiếu lao động; luồng di chuyển không hiệu quả.", "Ứng dụng logistics": "Vận chuyển pallet/thùng giữa khu nhận, lưu trữ, picking và đóng gói.", "Điều kiện triển khai": "Cần mặt bằng kho phù hợp, lối đi được bố trí rõ ràng, hạ tầng kết nối và trạm sạc; có hệ thống điều phối, quy trình an toàn và nhân sự bảo trì robot.", "Dữ liệu cần có": "Mặt bằng và luồng kho; tải trọng; an toàn người-máy; hệ thống điều phối; hạ tầng sạc và bảo trì.", "Lợi ích": "Có thể giảm thao tác di chuyển thủ công và cải thiện tính ổn định của luồng vật liệu.", "Hạn chế/rủi ro": "Đầu tư ban đầu và thay đổi layout; điểm nghẽn có thể chuyển vị trí; cần đánh giá ROI và an toàn.", "Nguồn": "UNCTAD Review of Maritime Transport 2024 (automation/digitalization port context): https://unctad.org/publication/review-maritime-transport-2024", "Người duyệt": "Chuyên gia tự động hóa kho", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC014','Quản trị AI · Quản trị rủi ro AI','Công nghệ: Quản trị AI
Nhóm: Quản trị rủi ro AI
Chức năng: Quy trình nhận diện, đánh giá, xử lý và giám sát rủi ro trong thiết kế, phát triển, triển khai và sử dụng hệ thống AI.
Vấn đề giải quyết: AI đưa ra khuyến nghị sai; thiếu minh bạch; rò rỉ dữ liệu; thiên lệch hoặc không có người chịu trách nhiệm.
Ứng dụng logistics: Đặt quy tắc chatbot phải dẫn nguồn, nêu độ không chắc chắn, không tự quyết định mua sắm/tuân thủ và chuyển người thật khi cần.
Điều kiện triển khai: Cần xác định phạm vi ứng dụng AI, đánh giá rủi ro về dữ liệu và bảo mật; thiết lập quy trình kiểm thử, giám sát, kiểm soát của con người và phân công trách nhiệm quản trị.
Dữ liệu cần có: Phân loại trường hợp sử dụng; quản lý dữ liệu; kiểm thử; giám sát; cơ chế khiếu nại và can thiệp con người.
Lợi ích: Tăng độ tin cậy, trách nhiệm giải trình và khả năng kiểm soát hệ thống AI.
Hạn chế/rủi ro: Khung quản trị không loại bỏ hoàn toàn rủi ro; cần điều chỉnh theo bối cảnh và cập nhật định kỳ.
Nguồn: NIST AI RMF: https://www.nist.gov/itl/ai-risk-management-framework; FAQ: https://www.nist.gov/itl/ai-risk-management-framework/ai-risk-management-framework-faqs
Ngày cập nhật: 2026-11-13T00:00:00','knowledge','Cần duyệt','Cong_nghe_CDS',false,'https://www.nist.gov/itl/ai-risk-management-framework','["https://www.nist.gov/itl/ai-risk-management-framework", "https://www.nist.gov/itl/ai-risk-management-framework/ai-risk-management-framework-faqs"]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 17}, "fields": {"ID": "TEC014", "Công nghệ": "Quản trị AI", "Nhóm": "Quản trị rủi ro AI", "Chức năng": "Quy trình nhận diện, đánh giá, xử lý và giám sát rủi ro trong thiết kế, phát triển, triển khai và sử dụng hệ thống AI.", "Vấn đề giải quyết": "AI đưa ra khuyến nghị sai; thiếu minh bạch; rò rỉ dữ liệu; thiên lệch hoặc không có người chịu trách nhiệm.", "Ứng dụng logistics": "Đặt quy tắc chatbot phải dẫn nguồn, nêu độ không chắc chắn, không tự quyết định mua sắm/tuân thủ và chuyển người thật khi cần.", "Điều kiện triển khai": "Cần xác định phạm vi ứng dụng AI, đánh giá rủi ro về dữ liệu và bảo mật; thiết lập quy trình kiểm thử, giám sát, kiểm soát của con người và phân công trách nhiệm quản trị.", "Dữ liệu cần có": "Phân loại trường hợp sử dụng; quản lý dữ liệu; kiểm thử; giám sát; cơ chế khiếu nại và can thiệp con người.", "Lợi ích": "Tăng độ tin cậy, trách nhiệm giải trình và khả năng kiểm soát hệ thống AI.", "Hạn chế/rủi ro": "Khung quản trị không loại bỏ hoàn toàn rủi ro; cần điều chỉnh theo bối cảnh và cập nhật định kỳ.", "Nguồn": "NIST AI RMF: https://www.nist.gov/itl/ai-risk-management-framework; FAQ: https://www.nist.gov/itl/ai-risk-management-framework/ai-risk-management-framework-faqs", "Người duyệt": "Phụ trách AI/tuân thủ", "Ngày cập nhật": "2026-11-13T00:00:00", "Trạng thái": "Cần duyệt"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC015','ERP · Hệ thống quản trị','Công nghệ: ERP
Nhóm: Hệ thống quản trị
Chức năng: Tích hợp và quản lý các nguồn lực, quy trình và dữ liệu của doanh nghiệp
Vấn đề giải quyết: Dữ liệu phân tán, khó kiểm soát tài chính, nhân sự, mua hàng và vận hành
Ứng dụng logistics: Quản lý đơn hàng, mua hàng, tồn kho, tài chính và chi phí logistics
Điều kiện triển khai: Quy trình nghiệp vụ tương đối chuẩn hóa; có dữ liệu nền; nhân sự được đào tạo
Dữ liệu cần có: Đơn hàng, khách hàng, nhà cung cấp, hàng tồn kho, tài chính, nhân sự
Lợi ích: Tập trung dữ liệu; tăng khả năng kiểm soát và phối hợp
Hạn chế/rủi ro: Chi phí triển khai và tùy chỉnh cao; thay đổi quy trình; phụ thuộc chất lượng dữ liệu
Nguồn: ITU – Recommendation Y.4910: Maturity Model of Digital Supply Chain; ASCM – How to Build a Digital Supply Chain.
