insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC016','WMS · Hệ thống quản trị','Công nghệ: WMS
Nhóm: Hệ thống quản trị
Chức năng: Quản lý nhập, xuất, lưu trữ, lấy hàng và kiểm kê
Vấn đề giải quyết: Sai lệch tồn kho, thất lạc hàng, xử lý đơn chậm, khó theo dõi vị trí hàng
Ứng dụng logistics: Quản lý vị trí lưu trữ, put-away, picking, packing, kiểm kê
Điều kiện triển khai: Có sơ đồ kho, mã vị trí, mã hàng và quy trình kho rõ ràng
Dữ liệu cần có: SKU, vị trí kho, số lượng, lô hàng, hạn sử dụng, giao dịch nhập xuất
Lợi ích: Tăng độ chính xác tồn kho; cải thiện năng suất và khả năng truy xuất
Hạn chế/rủi ro: Cần chuẩn hóa dữ liệu; nhân viên phải thay đổi cách làm; tích hợp có thể phức tạp
Nguồn: ITU – Y.4910; GS1 – GS1 System Architecture
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Cong_nghe_CDS',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 19}, "fields": {"ID": "TEC016", "Công nghệ": "WMS", "Nhóm": "Hệ thống quản trị", "Chức năng": "Quản lý nhập, xuất, lưu trữ, lấy hàng và kiểm kê", "Vấn đề giải quyết": "Sai lệch tồn kho, thất lạc hàng, xử lý đơn chậm, khó theo dõi vị trí hàng", "Ứng dụng logistics": "Quản lý vị trí lưu trữ, put-away, picking, packing, kiểm kê", "Điều kiện triển khai": "Có sơ đồ kho, mã vị trí, mã hàng và quy trình kho rõ ràng", "Dữ liệu cần có": "SKU, vị trí kho, số lượng, lô hàng, hạn sử dụng, giao dịch nhập xuất", "Lợi ích": "Tăng độ chính xác tồn kho; cải thiện năng suất và khả năng truy xuất", "Hạn chế/rủi ro": "Cần chuẩn hóa dữ liệu; nhân viên phải thay đổi cách làm; tích hợp có thể phức tạp", "Nguồn": "ITU – Y.4910; GS1 – GS1 System Architecture", "Người duyệt": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC017','TMS · Hệ thống quản trị','Công nghệ: TMS
Nhóm: Hệ thống quản trị
Chức năng: Lập kế hoạch, điều phối, theo dõi và kiểm soát hoạt động vận tải
Vấn đề giải quyết: Khó tối ưu tuyến đường, phương tiện, chi phí và tiến độ giao hàng
Ứng dụng logistics: Điều phối xe, lập tuyến, quản lý đơn vận chuyển, theo dõi giao hàng và đối soát cước
Điều kiện triển khai: Có dữ liệu phương tiện, tài xế, tuyến đường và đơn vận chuyển
Dữ liệu cần có: Điểm lấy/giao hàng, tải trọng, chi phí, lịch trình, GPS, trạng thái đơn
Lợi ích: Tối ưu sử dụng phương tiện; tăng khả năng theo dõi; kiểm soát chi phí
Hạn chế/rủi ro: Phụ thuộc độ chính xác dữ liệu; GPS và bản đồ có thể phát sinh chi phí
Nguồn: CSCMP – Supply Chain Management Definitions and Glossary; ASCM – SCOR Digital Standard
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Cong_nghe_CDS',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 20}, "fields": {"ID": "TEC017", "Công nghệ": "TMS", "Nhóm": "Hệ thống quản trị", "Chức năng": "Lập kế hoạch, điều phối, theo dõi và kiểm soát hoạt động vận tải", "Vấn đề giải quyết": "Khó tối ưu tuyến đường, phương tiện, chi phí và tiến độ giao hàng", "Ứng dụng logistics": "Điều phối xe, lập tuyến, quản lý đơn vận chuyển, theo dõi giao hàng và đối soát cước", "Điều kiện triển khai": "Có dữ liệu phương tiện, tài xế, tuyến đường và đơn vận chuyển", "Dữ liệu cần có": "Điểm lấy/giao hàng, tải trọng, chi phí, lịch trình, GPS, trạng thái đơn", "Lợi ích": "Tối ưu sử dụng phương tiện; tăng khả năng theo dõi; kiểm soát chi phí", "Hạn chế/rủi ro": "Phụ thuộc độ chính xác dữ liệu; GPS và bản đồ có thể phát sinh chi phí", "Nguồn": "CSCMP – Supply Chain Management Definitions and Glossary; ASCM – SCOR Digital Standard", "Người duyệt": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC018','SCM · Hệ thống quản trị','Công nghệ: SCM
Nhóm: Hệ thống quản trị
Chức năng: Hỗ trợ lập kế hoạch, phối hợp và kiểm soát dòng hàng hóa, thông tin và nguồn lực trong chuỗi cung ứng
Vấn đề giải quyết: Thiếu liên kết giữa mua hàng, sản xuất, kho, vận tải và phân phối
Ứng dụng logistics: Lập kế hoạch cung ứng, phối hợp nhà cung cấp, quản lý đơn hàng và phân phối
Điều kiện triển khai: Có dữ liệu liên phòng ban; đối tác sẵn sàng chia sẻ dữ liệu; quy trình phối hợp rõ ràng
Dữ liệu cần có: Nhu cầu, tồn kho, năng lực cung ứng, đơn hàng, lịch sản xuất và vận chuyển
Lợi ích: Tăng khả năng phối hợp; cải thiện lập kế hoạch và khả năng phản ứng
Hạn chế/rủi ro: Khó tích hợp nhiều đối tác; yêu cầu quản trị dữ liệu và thay đổi tổ chức
Nguồn: CSCMP – Supply Chain Management Definitions and Glossary; ASCM – SCOR Digital Standard
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Cong_nghe_CDS',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 21}, "fields": {"ID": "TEC018", "Công nghệ": "SCM", "Nhóm": "Hệ thống quản trị", "Chức năng": "Hỗ trợ lập kế hoạch, phối hợp và kiểm soát dòng hàng hóa, thông tin và nguồn lực trong chuỗi cung ứng", "Vấn đề giải quyết": "Thiếu liên kết giữa mua hàng, sản xuất, kho, vận tải và phân phối", "Ứng dụng logistics": "Lập kế hoạch cung ứng, phối hợp nhà cung cấp, quản lý đơn hàng và phân phối", "Điều kiện triển khai": "Có dữ liệu liên phòng ban; đối tác sẵn sàng chia sẻ dữ liệu; quy trình phối hợp rõ ràng", "Dữ liệu cần có": "Nhu cầu, tồn kho, năng lực cung ứng, đơn hàng, lịch sản xuất và vận chuyển", "Lợi ích": "Tăng khả năng phối hợp; cải thiện lập kế hoạch và khả năng phản ứng", "Hạn chế/rủi ro": "Khó tích hợp nhiều đối tác; yêu cầu quản trị dữ liệu và thay đổi tổ chức", "Nguồn": "CSCMP – Supply Chain Management Definitions and Glossary; ASCM – SCOR Digital Standard", "Người duyệt": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC019','EDI · Kết nối và tích hợp','Công nghệ: EDI
Nhóm: Kết nối và tích hợp
Chức năng: Trao đổi chứng từ, thông điệp kinh doanh theo định dạng điện tử tiêu chuẩn
Vấn đề giải quyết: Nhập liệu thủ công, sai sót chứng từ, trao đổi thông tin chậm
Ứng dụng logistics: Trao đổi đơn đặt hàng, hóa đơn, thông báo giao hàng, chứng từ vận tải
Điều kiện triển khai: Đối tác thống nhất chuẩn dữ liệu; có hệ thống kết nối và quy trình trao đổi
Dữ liệu cần có: Mã hàng, mã đối tác, đơn hàng, hóa đơn, thông tin giao nhận
Lợi ích: Giảm thao tác thủ công; tăng tốc độ và tính nhất quán của giao dịch
Hạn chế/rủi ro: Chi phí kết nối ban đầu; khác biệt chuẩn dữ liệu giữa các đối tác
Nguồn: GS1 US – Application of GS1 System of Standards to Support Traceability.
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Cong_nghe_CDS',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 22}, "fields": {"ID": "TEC019", "Công nghệ": "EDI", "Nhóm": "Kết nối và tích hợp", "Chức năng": "Trao đổi chứng từ, thông điệp kinh doanh theo định dạng điện tử tiêu chuẩn", "Vấn đề giải quyết": "Nhập liệu thủ công, sai sót chứng từ, trao đổi thông tin chậm", "Ứng dụng logistics": "Trao đổi đơn đặt hàng, hóa đơn, thông báo giao hàng, chứng từ vận tải", "Điều kiện triển khai": "Đối tác thống nhất chuẩn dữ liệu; có hệ thống kết nối và quy trình trao đổi", "Dữ liệu cần có": "Mã hàng, mã đối tác, đơn hàng, hóa đơn, thông tin giao nhận", "Lợi ích": "Giảm thao tác thủ công; tăng tốc độ và tính nhất quán của giao dịch", "Hạn chế/rủi ro": "Chi phí kết nối ban đầu; khác biệt chuẩn dữ liệu giữa các đối tác", "Nguồn": "GS1 US – Application of GS1 System of Standards to Support Traceability.", "Người duyệt": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC020','API · Kết nối và tích hợp','Công nghệ: API
Nhóm: Kết nối và tích hợp
Chức năng: Cho phép các phần mềm trao đổi dữ liệu và gọi chức năng của nhau
Vấn đề giải quyết: Hệ thống hoạt động riêng lẻ, phải nhập dữ liệu nhiều lần
Ứng dụng logistics: Kết nối ERP, WMS, TMS, sàn thương mại điện tử, nền tảng theo dõi đơn hàng
Điều kiện triển khai: Hệ thống có API hoặc có giải pháp trung gian; có nhân sự kỹ thuật quản lý kết nối
Dữ liệu cần có: Mã đơn hàng, trạng thái vận chuyển, tồn kho, thông tin khách hàng và đối tác
Lợi ích: Đồng bộ dữ liệu nhanh; giảm nhập liệu trùng lặp; mở rộng kết nối
Hạn chế/rủi ro: Rủi ro bảo mật; lỗi tương thích; phụ thuộc tài liệu và giới hạn API
Nguồn: OpenAPI Initiative – OpenAPI Specification.
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Cong_nghe_CDS',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 23}, "fields": {"ID": "TEC020", "Công nghệ": "API", "Nhóm": "Kết nối và tích hợp", "Chức năng": "Cho phép các phần mềm trao đổi dữ liệu và gọi chức năng của nhau", "Vấn đề giải quyết": "Hệ thống hoạt động riêng lẻ, phải nhập dữ liệu nhiều lần", "Ứng dụng logistics": "Kết nối ERP, WMS, TMS, sàn thương mại điện tử, nền tảng theo dõi đơn hàng", "Điều kiện triển khai": "Hệ thống có API hoặc có giải pháp trung gian; có nhân sự kỹ thuật quản lý kết nối", "Dữ liệu cần có": "Mã đơn hàng, trạng thái vận chuyển, tồn kho, thông tin khách hàng và đối tác", "Lợi ích": "Đồng bộ dữ liệu nhanh; giảm nhập liệu trùng lặp; mở rộng kết nối", "Hạn chế/rủi ro": "Rủi ro bảo mật; lỗi tương thích; phụ thuộc tài liệu và giới hạn API", "Nguồn": "OpenAPI Initiative – OpenAPI Specification.", "Người duyệt": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC021','Cloud Computing · Hạ tầng số','Công nghệ: Cloud Computing
Nhóm: Hạ tầng số
Chức năng: Cung cấp tài nguyên lưu trữ, máy chủ và phần mềm qua Internet
Vấn đề giải quyết: Hạ tầng CNTT thiếu linh hoạt, chi phí đầu tư máy chủ ban đầu lớn
Ứng dụng logistics: Lưu trữ dữ liệu vận tải, vận hành WMS/TMS trực tuyến, chia sẻ dữ liệu giữa các chi nhánh
Điều kiện triển khai: Kết nối Internet ổn định; lựa chọn nhà cung cấp; có chính sách bảo mật và sao lưu
Dữ liệu cần có: Dữ liệu vận hành, dữ liệu khách hàng, đơn hàng, chứng từ và nhật ký hệ thống
Lợi ích: Linh hoạt mở rộng; giảm nhu cầu đầu tư hạ tầng tại chỗ; hỗ trợ truy cập từ xa
Hạn chế/rủi ro: Phụ thuộc nhà cung cấp và Internet; rủi ro rò rỉ dữ liệu; chi phí thuê dài hạn
Nguồn: NIST – The NIST Definition of Cloud Computing (SP 800-145).
