insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC022','IoT · Thu thập dữ liệu và giám sát','Công nghệ: IoT
Nhóm: Thu thập dữ liệu và giám sát
Chức năng: Kết nối cảm biến và thiết bị để thu thập, truyền dữ liệu tự động
Vấn đề giải quyết: Thiếu dữ liệu thời gian thực về hàng hóa, phương tiện và điều kiện bảo quản
Ứng dụng logistics: Giám sát nhiệt độ container lạnh, độ ẩm kho, vị trí và trạng thái phương tiện
Điều kiện triển khai: Có cảm biến phù hợp, kết nối mạng, nền tảng tiếp nhận và xử lý dữ liệu
Dữ liệu cần có: Nhiệt độ, độ ẩm, vị trí, thời gian, trạng thái thiết bị
Lợi ích: Tăng khả năng giám sát; cảnh báo sớm; hỗ trợ truy xuất và kiểm soát chất lượng
Hạn chế/rủi ro: Chi phí thiết bị; mất kết nối; sai lệch cảm biến; rủi ro an ninh mạng
Nguồn: ISO – Internet of Things and Digital Twin; GS1 – EPCIS Standard.
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Cong_nghe_CDS',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 25}, "fields": {"ID": "TEC022", "Công nghệ": "IoT", "Nhóm": "Thu thập dữ liệu và giám sát", "Chức năng": "Kết nối cảm biến và thiết bị để thu thập, truyền dữ liệu tự động", "Vấn đề giải quyết": "Thiếu dữ liệu thời gian thực về hàng hóa, phương tiện và điều kiện bảo quản", "Ứng dụng logistics": "Giám sát nhiệt độ container lạnh, độ ẩm kho, vị trí và trạng thái phương tiện", "Điều kiện triển khai": "Có cảm biến phù hợp, kết nối mạng, nền tảng tiếp nhận và xử lý dữ liệu", "Dữ liệu cần có": "Nhiệt độ, độ ẩm, vị trí, thời gian, trạng thái thiết bị", "Lợi ích": "Tăng khả năng giám sát; cảnh báo sớm; hỗ trợ truy xuất và kiểm soát chất lượng", "Hạn chế/rủi ro": "Chi phí thiết bị; mất kết nối; sai lệch cảm biến; rủi ro an ninh mạng", "Nguồn": "ISO – Internet of Things and Digital Twin; GS1 – EPCIS Standard.", "Người duyệt": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC023','GPS và Telematics · Thu thập dữ liệu và giám sát','Công nghệ: GPS và Telematics
Nhóm: Thu thập dữ liệu và giám sát
Chức năng: Xác định vị trí và thu thập dữ liệu hoạt động của phương tiện
Vấn đề giải quyết: Không nắm được vị trí xe, khó giám sát hành trình và mức sử dụng phương tiện
Ứng dụng logistics: Theo dõi xe giao hàng, giám sát hành trình, phân tích thời gian dừng và quãng đường
Điều kiện triển khai: Thiết bị định vị; kết nối truyền dữ liệu; phần mềm quản lý đội xe
Dữ liệu cần có: Tọa độ, thời gian, tốc độ, quãng đường, trạng thái xe và lịch trình
Lợi ích: Tăng khả năng giám sát; hỗ trợ điều phối và kiểm soát hành trình
Hạn chế/rủi ro: Mất tín hiệu; sai số định vị; vấn đề quyền riêng tư và quản lý dữ liệu tài xế
Nguồn: GPS.gov – GPS Accuracy; ITU – Digital Supply Chain Maturity Model.
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Cong_nghe_CDS',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 26}, "fields": {"ID": "TEC023", "Công nghệ": "GPS và Telematics", "Nhóm": "Thu thập dữ liệu và giám sát", "Chức năng": "Xác định vị trí và thu thập dữ liệu hoạt động của phương tiện", "Vấn đề giải quyết": "Không nắm được vị trí xe, khó giám sát hành trình và mức sử dụng phương tiện", "Ứng dụng logistics": "Theo dõi xe giao hàng, giám sát hành trình, phân tích thời gian dừng và quãng đường", "Điều kiện triển khai": "Thiết bị định vị; kết nối truyền dữ liệu; phần mềm quản lý đội xe", "Dữ liệu cần có": "Tọa độ, thời gian, tốc độ, quãng đường, trạng thái xe và lịch trình", "Lợi ích": "Tăng khả năng giám sát; hỗ trợ điều phối và kiểm soát hành trình", "Hạn chế/rủi ro": "Mất tín hiệu; sai số định vị; vấn đề quyền riêng tư và quản lý dữ liệu tài xế", "Nguồn": "GPS.gov – GPS Accuracy; ITU – Digital Supply Chain Maturity Model.", "Người duyệt": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC024','Barcode · Nhận dạng và truy xuất','Công nghệ: Barcode
Nhóm: Nhận dạng và truy xuất
Chức năng: Nhận dạng hàng hóa thông qua mã được in và quét bằng thiết bị đọc
Vấn đề giải quyết: Nhập liệu thủ công, nhầm lẫn mã hàng và sai lệch trong kiểm kê
Ứng dụng logistics: Quét mã khi nhập kho, xuất kho, phân loại và giao nhận
Điều kiện triển khai: Có hệ thống mã hóa thống nhất; máy in và máy quét; phần mềm ghi nhận giao dịch
Dữ liệu cần có: Mã hàng, mã kiện, mã lô, vị trí và thời điểm quét
Lợi ích: Chi phí tương đối thấp; dễ triển khai; giảm sai sót nhập liệu
Hạn chế/rủi ro: Cần quét trực tiếp; mã có thể bị mờ, rách hoặc hư hỏng
Nguồn: GS1 – GS1 System Architecture; GS1 – Standards and Barcodes.
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Cong_nghe_CDS',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 27}, "fields": {"ID": "TEC024", "Công nghệ": "Barcode", "Nhóm": "Nhận dạng và truy xuất", "Chức năng": "Nhận dạng hàng hóa thông qua mã được in và quét bằng thiết bị đọc", "Vấn đề giải quyết": "Nhập liệu thủ công, nhầm lẫn mã hàng và sai lệch trong kiểm kê", "Ứng dụng logistics": "Quét mã khi nhập kho, xuất kho, phân loại và giao nhận", "Điều kiện triển khai": "Có hệ thống mã hóa thống nhất; máy in và máy quét; phần mềm ghi nhận giao dịch", "Dữ liệu cần có": "Mã hàng, mã kiện, mã lô, vị trí và thời điểm quét", "Lợi ích": "Chi phí tương đối thấp; dễ triển khai; giảm sai sót nhập liệu", "Hạn chế/rủi ro": "Cần quét trực tiếp; mã có thể bị mờ, rách hoặc hư hỏng", "Nguồn": "GS1 – GS1 System Architecture; GS1 – Standards and Barcodes.", "Người duyệt": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC025','RFID · Nhận dạng và truy xuất','Công nghệ: RFID
Nhóm: Nhận dạng và truy xuất
Chức năng: Nhận dạng đối tượng bằng thẻ RFID và đầu đọc sóng vô tuyến
Vấn đề giải quyết: Khó nhận dạng nhanh số lượng lớn hàng hóa; phải quét từng mã bằng thao tác trực tiếp
Ứng dụng logistics: Kiểm kê pallet, theo dõi tài sản luân chuyển, nhận diện hàng qua cổng kho
Điều kiện triển khai: Thẻ RFID, đầu đọc, vùng đọc phù hợp; hệ thống liên kết mã định danh
Dữ liệu cần có: Mã định danh, vị trí đọc, thời gian, trạng thái và thông tin hàng hóa
Lợi ích: Có thể đọc nhiều thẻ nhanh; không nhất thiết cần nhìn trực tiếp vào mã
Hạn chế/rủi ro: Chi phí thẻ và đầu đọc; nhiễu sóng; vật liệu và môi trường có thể ảnh hưởng khả năng đọc
Nguồn: GS1 – EPC/RFID Standards; GS1 – GS1 System Architecture.
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Cong_nghe_CDS',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 28}, "fields": {"ID": "TEC025", "Công nghệ": "RFID", "Nhóm": "Nhận dạng và truy xuất", "Chức năng": "Nhận dạng đối tượng bằng thẻ RFID và đầu đọc sóng vô tuyến", "Vấn đề giải quyết": "Khó nhận dạng nhanh số lượng lớn hàng hóa; phải quét từng mã bằng thao tác trực tiếp", "Ứng dụng logistics": "Kiểm kê pallet, theo dõi tài sản luân chuyển, nhận diện hàng qua cổng kho", "Điều kiện triển khai": "Thẻ RFID, đầu đọc, vùng đọc phù hợp; hệ thống liên kết mã định danh", "Dữ liệu cần có": "Mã định danh, vị trí đọc, thời gian, trạng thái và thông tin hàng hóa", "Lợi ích": "Có thể đọc nhiều thẻ nhanh; không nhất thiết cần nhìn trực tiếp vào mã", "Hạn chế/rủi ro": "Chi phí thẻ và đầu đọc; nhiễu sóng; vật liệu và môi trường có thể ảnh hưởng khả năng đọc", "Nguồn": "GS1 – EPC/RFID Standards; GS1 – GS1 System Architecture.", "Người duyệt": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC026','AI/ML · Phân tích và hỗ trợ quyết định','Công nghệ: AI/ML
Nhóm: Phân tích và hỗ trợ quyết định
Chức năng: Phân tích dữ liệu, nhận diện mẫu, dự báo và đề xuất phương án
Vấn đề giải quyết: Khó dự báo nhu cầu, phân bổ nguồn lực và phát hiện bất thường bằng phương pháp thủ công
Ứng dụng logistics: Dự báo nhu cầu vận tải, dự báo tồn kho, dự đoán thời gian giao hàng, tối ưu tuyến
Điều kiện triển khai: Có dữ liệu đủ lớn và đáng tin cậy; xác định bài toán; có năng lực kiểm thử mô hình
Dữ liệu cần có: Lịch sử đơn hàng, nhu cầu, tồn kho, thời gian giao hàng, chi phí, dữ liệu tuyến
Lợi ích: Hỗ trợ ra quyết định; dự báo tốt hơn khi dữ liệu phù hợp; giảm công việc phân tích lặp lại
Hạn chế/rủi ro: Dữ liệu thiên lệch; dự báo sai; khó giải thích; cần giám sát con người
Nguồn: NIST – AI Risk Management Framework; OECD – Digitalisation of SMEs.
