insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC028','RPA · Tự động hóa','Công nghệ: RPA
Nhóm: Tự động hóa
Chức năng: Tự động thực hiện các thao tác lặp lại trên phần mềm theo quy tắc
Vấn đề giải quyết: Nhập liệu, đối chiếu chứng từ và lập báo cáo tốn thời gian
Ứng dụng logistics: Nhập đơn hàng, đối chiếu hóa đơn, cập nhật trạng thái và tổng hợp báo cáo
Điều kiện triển khai: Quy trình lặp lại, ổn định và có quy tắc rõ; phần mềm có thể truy cập
Dữ liệu cần có: Biểu mẫu, hóa đơn, đơn hàng, dữ liệu đối chiếu và quy tắc xử lý
Lợi ích: Giảm thao tác thủ công; tăng tốc độ xử lý; giảm lỗi nhập liệu
Hạn chế/rủi ro: Khó xử lý ngoại lệ; thay đổi giao diện phần mềm có thể làm robot lỗi
Nguồn: Microsoft – Power Automate Desktop Flows.
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Cong_nghe_CDS',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 31}, "fields": {"ID": "TEC028", "Công nghệ": "RPA", "Nhóm": "Tự động hóa", "Chức năng": "Tự động thực hiện các thao tác lặp lại trên phần mềm theo quy tắc", "Vấn đề giải quyết": "Nhập liệu, đối chiếu chứng từ và lập báo cáo tốn thời gian", "Ứng dụng logistics": "Nhập đơn hàng, đối chiếu hóa đơn, cập nhật trạng thái và tổng hợp báo cáo", "Điều kiện triển khai": "Quy trình lặp lại, ổn định và có quy tắc rõ; phần mềm có thể truy cập", "Dữ liệu cần có": "Biểu mẫu, hóa đơn, đơn hàng, dữ liệu đối chiếu và quy tắc xử lý", "Lợi ích": "Giảm thao tác thủ công; tăng tốc độ xử lý; giảm lỗi nhập liệu", "Hạn chế/rủi ro": "Khó xử lý ngoại lệ; thay đổi giao diện phần mềm có thể làm robot lỗi", "Nguồn": "Microsoft – Power Automate Desktop Flows.", "Người duyệt": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC029','Blockchain · Dữ liệu và truy xuất','Công nghệ: Blockchain
Nhóm: Dữ liệu và truy xuất
Chức năng: Ghi nhận giao dịch theo cấu trúc phân tán, hỗ trợ kiểm tra tính toàn vẹn dữ liệu
Vấn đề giải quyết: Khó xác minh lịch sử giao dịch và mức độ tin cậy của dữ liệu giữa nhiều bên
Ứng dụng logistics: Chia sẻ sự kiện giao nhận, truy xuất nguồn gốc và xác minh lịch sử luân chuyển hàng
Điều kiện triển khai: Các bên tham gia thống nhất quy tắc, dữ liệu và quyền truy cập; có mô hình quản trị
Dữ liệu cần có: Mã định danh, sự kiện giao dịch, thời gian, địa điểm và thông tin xác nhận
Lợi ích: Tăng khả năng kiểm chứng lịch sử dữ liệu; hỗ trợ phối hợp giữa các bên
Hạn chế/rủi ro: Chi phí và độ phức tạp; dữ liệu sai khi nhập vẫn có thể được ghi nhận; khó mở rộng nếu thiếu đồng thuận
Nguồn: NIST – Blockchain Technology Overview (NISTIR 8202); GS1 – EPCIS Standard.
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Cong_nghe_CDS',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 32}, "fields": {"ID": "TEC029", "Công nghệ": "Blockchain", "Nhóm": "Dữ liệu và truy xuất", "Chức năng": "Ghi nhận giao dịch theo cấu trúc phân tán, hỗ trợ kiểm tra tính toàn vẹn dữ liệu", "Vấn đề giải quyết": "Khó xác minh lịch sử giao dịch và mức độ tin cậy của dữ liệu giữa nhiều bên", "Ứng dụng logistics": "Chia sẻ sự kiện giao nhận, truy xuất nguồn gốc và xác minh lịch sử luân chuyển hàng", "Điều kiện triển khai": "Các bên tham gia thống nhất quy tắc, dữ liệu và quyền truy cập; có mô hình quản trị", "Dữ liệu cần có": "Mã định danh, sự kiện giao dịch, thời gian, địa điểm và thông tin xác nhận", "Lợi ích": "Tăng khả năng kiểm chứng lịch sử dữ liệu; hỗ trợ phối hợp giữa các bên", "Hạn chế/rủi ro": "Chi phí và độ phức tạp; dữ liệu sai khi nhập vẫn có thể được ghi nhận; khó mở rộng nếu thiếu đồng thuận", "Nguồn": "NIST – Blockchain Technology Overview (NISTIR 8202); GS1 – EPCIS Standard.", "Người duyệt": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC030','Digital Twin · Mô phỏng và tối ưu','Công nghệ: Digital Twin
Nhóm: Mô phỏng và tối ưu
Chức năng: Tạo mô hình số của đối tượng hoặc quy trình thực tế để theo dõi, mô phỏng và phân tích
Vấn đề giải quyết: Khó đánh giá tác động của thay đổi trước khi triển khai thực tế
Ứng dụng logistics: Mô phỏng bố trí kho, luồng hàng, hoạt động đội xe và mạng lưới phân phối
Điều kiện triển khai: Có dữ liệu cập nhật; mô hình quy trình; cảm biến hoặc kết nối với hệ thống vận hành
Dữ liệu cần có: Sơ đồ kho, luồng hàng, tồn kho, dữ liệu vận tải, thời gian và năng lực thiết bị
Lợi ích: Hỗ trợ thử nghiệm kịch bản; nhận diện điểm nghẽn; tối ưu nguồn lực
Hạn chế/rủi ro: Chi phí xây dựng mô hình; yêu cầu dữ liệu chất lượng cao; khó duy trì đồng bộ với thực tế
Nguồn: ISO – ISO/IEC TR 30172:2023 – Digital Twin Use Cases; ITU – Y.4910.
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Cong_nghe_CDS',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 33}, "fields": {"ID": "TEC030", "Công nghệ": "Digital Twin", "Nhóm": "Mô phỏng và tối ưu", "Chức năng": "Tạo mô hình số của đối tượng hoặc quy trình thực tế để theo dõi, mô phỏng và phân tích", "Vấn đề giải quyết": "Khó đánh giá tác động của thay đổi trước khi triển khai thực tế", "Ứng dụng logistics": "Mô phỏng bố trí kho, luồng hàng, hoạt động đội xe và mạng lưới phân phối", "Điều kiện triển khai": "Có dữ liệu cập nhật; mô hình quy trình; cảm biến hoặc kết nối với hệ thống vận hành", "Dữ liệu cần có": "Sơ đồ kho, luồng hàng, tồn kho, dữ liệu vận tải, thời gian và năng lực thiết bị", "Lợi ích": "Hỗ trợ thử nghiệm kịch bản; nhận diện điểm nghẽn; tối ưu nguồn lực", "Hạn chế/rủi ro": "Chi phí xây dựng mô hình; yêu cầu dữ liệu chất lượng cao; khó duy trì đồng bộ với thực tế", "Nguồn": "ISO – ISO/IEC TR 30172:2023 – Digital Twin Use Cases; ITU – Y.4910.", "Người duyệt": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC031','AGV/AMR · Robot và tự động hóa vật lý','Công nghệ: AGV/AMR
Nhóm: Robot và tự động hóa vật lý
Chức năng: Tự động vận chuyển hàng hóa trong khu vực kho hoặc nhà máy
Vấn đề giải quyết: Phụ thuộc nhiều vào vận chuyển thủ công; di chuyển nội bộ tốn nhân lực
Ứng dụng logistics: Vận chuyển pallet, thùng hàng giữa khu nhận hàng, lưu trữ và đóng gói
Điều kiện triển khai: Mặt bằng phù hợp; quy trình di chuyển ổn định; hạ tầng định vị và an toàn
Dữ liệu cần có: Bản đồ kho, điểm lấy/trả hàng, tải trọng, lệnh vận chuyển và trạng thái robot
Lợi ích: Giảm thao tác vận chuyển thủ công; hỗ trợ hoạt động liên tục
Hạn chế/rủi ro: Đầu tư cao; cần bảo trì; phải điều chỉnh mặt bằng và quy trình an toàn
Nguồn: ISO – ISO 3691-4:2023 – Driverless Industrial Trucks; ASCM – How to Build a Digital Supply Chain
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Cong_nghe_CDS',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 34}, "fields": {"ID": "TEC031", "Công nghệ": "AGV/AMR", "Nhóm": "Robot và tự động hóa vật lý", "Chức năng": "Tự động vận chuyển hàng hóa trong khu vực kho hoặc nhà máy", "Vấn đề giải quyết": "Phụ thuộc nhiều vào vận chuyển thủ công; di chuyển nội bộ tốn nhân lực", "Ứng dụng logistics": "Vận chuyển pallet, thùng hàng giữa khu nhận hàng, lưu trữ và đóng gói", "Điều kiện triển khai": "Mặt bằng phù hợp; quy trình di chuyển ổn định; hạ tầng định vị và an toàn", "Dữ liệu cần có": "Bản đồ kho, điểm lấy/trả hàng, tải trọng, lệnh vận chuyển và trạng thái robot", "Lợi ích": "Giảm thao tác vận chuyển thủ công; hỗ trợ hoạt động liên tục", "Hạn chế/rủi ro": "Đầu tư cao; cần bảo trì; phải điều chỉnh mặt bằng và quy trình an toàn", "Nguồn": "ISO – ISO 3691-4:2023 – Driverless Industrial Trucks; ASCM – How to Build a Digital Supply Chain", "Người duyệt": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC032','AS/RS · Robot và tự động hóa vật lý','Công nghệ: AS/RS
Nhóm: Robot và tự động hóa vật lý
Chức năng: Tự động hóa việc lưu trữ và lấy hàng trong kho
Vấn đề giải quyết: Tốn diện tích, thao tác lấy hàng chậm và phụ thuộc nhân công
Ứng dụng logistics: Lưu trữ pallet, khay hàng và tự động lấy hàng theo lệnh
Điều kiện triển khai: Kho có thiết kế phù hợp; hàng hóa và kích thước tương thích; WMS kết nối được
Dữ liệu cần có: Mã hàng, vị trí lưu trữ, kích thước, tải trọng, lệnh nhập/xuất
Lợi ích: Tăng mật độ lưu trữ; giảm thao tác thủ công; tăng khả năng kiểm soát
Hạn chế/rủi ro: Chi phí đầu tư và bảo trì lớn; yêu cầu kỹ thuật cao; gián đoạn có thể ảnh hưởng toàn hệ thống
Nguồn: ASCM – How to Build a Digital Supply Chain; ITU – Y.4910.
Ngày cập nhật: 2026-11-14T00:00:00','knowledge','Chờ xác minh','Cong_nghe_CDS',false,null,'[]'::jsonb,'{"origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Cong_nghe_CDS", "row": 35}, "fields": {"ID": "TEC032", "Công nghệ": "AS/RS", "Nhóm": "Robot và tự động hóa vật lý", "Chức năng": "Tự động hóa việc lưu trữ và lấy hàng trong kho", "Vấn đề giải quyết": "Tốn diện tích, thao tác lấy hàng chậm và phụ thuộc nhân công", "Ứng dụng logistics": "Lưu trữ pallet, khay hàng và tự động lấy hàng theo lệnh", "Điều kiện triển khai": "Kho có thiết kế phù hợp; hàng hóa và kích thước tương thích; WMS kết nối được", "Dữ liệu cần có": "Mã hàng, vị trí lưu trữ, kích thước, tải trọng, lệnh nhập/xuất", "Lợi ích": "Tăng mật độ lưu trữ; giảm thao tác thủ công; tăng khả năng kiểm soát", "Hạn chế/rủi ro": "Chi phí đầu tư và bảo trì lớn; yêu cầu kỹ thuật cao; gián đoạn có thể ảnh hưởng toàn hệ thống", "Nguồn": "ASCM – How to Build a Digital Supply Chain; ITU – Y.4910.", "Người duyệt": "Chưa phân công", "Ngày cập nhật": "2026-11-14T00:00:00", "Trạng thái": "Chờ xác minh"}}'::jsonb) on conflict(external_id) do nothing;
insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC033','Computer Vision · AI và nhận dạng hình ảnh','Công nghệ: Computer Vision
Nhóm: AI và nhận dạng hình ảnh
Chức năng: Phân tích hình ảnh/video để nhận diện vật thể, tình trạng hoặc hành vi
Vấn đề giải quyết: Kiểm tra hàng hóa và giám sát hoạt động bằng mắt thường mất thời gian
Ứng dụng logistics: Nhận diện kiện hàng, kiểm tra hư hỏng bao bì, giám sát khu vực kho và hỗ trợ đếm hàng
Điều kiện triển khai: Camera phù hợp; điều kiện ánh sáng; mô hình nhận diện được huấn luyện và kiểm thử
Dữ liệu cần có: Hình ảnh, video, nhãn dữ liệu, tiêu chí lỗi và thông tin đối tượng
Lợi ích: Tự động hóa kiểm tra; tăng tốc độ nhận diện; hỗ trợ giám sát
Hạn chế/rủi ro: Nhận diện sai do góc quay, ánh sáng hoặc vật cản; vấn đề quyền riêng tư
Nguồn: NIST – AI Risk Management Framework; ISO – Artificial Intelligence Standards Committee.
