insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('TEC034','Cybersecurity · Bảo mật và quản trị dữ liệu','Công nghệ: Cybersecurity
Nhóm: Bảo mật và quản trị dữ liệu
Chức năng: Bảo vệ hệ thống, thiết bị và dữ liệu trước truy cập trái phép, tấn công hoặc gián đoạn
Vấn đề giải quyết: Nguy cơ rò rỉ dữ liệu, mất dữ liệu và gián đoạn hoạt động logistics
Ứng dụng logistics: Bảo vệ ERP/WMS/TMS, tài khoản nhân viên, dữ liệu khách hàng và kết nối đối tác
Điều kiện triển khai: Có chính sách bảo mật; phân quyền; sao lưu; cập nhật hệ thống; đào tạo nhân sự
Dữ liệu cần có: Tài khoản, nhật ký truy cập, dữ liệu hệ thống, danh mục tài sản CNTT và sự cố
Lợi ích: Giảm rủi ro an ninh; tăng khả năng duy trì hoạt động và bảo vệ dữ liệu
Hạn chế/rủi ro: Không loại bỏ hoàn toàn rủi ro; cần đầu tư và cập nhật liên tục; yếu tố con người vẫn là điểm dễ bị tấn công
Nguồn: NIST – Cybersecurity Framework 2.0; OECD – Digitalisation of SMEs.
