insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('MKT006','Khảo sát rào cản số hóa SME 2025 · Chi phí chuyển đổi số','Chủ đề: Chi phí chuyển đổi số
Chỉ tiêu/nội dung: Khảo sát rào cản số hóa SME 2025
Giá trị/tóm tắt: Báo cáo OECD 2025 cho thấy trong mẫu khảo sát đa quốc gia, các rào cản được nêu gồm chi phí bảo trì phần mềm, thiếu thời gian đào tạo, chi phí phần cứng và chi phí đào tạo.
Đơn vị: Tỷ lệ phản hồi khảo sát
Phạm vi địa lý: Mẫu khảo sát các quốc gia tham gia OECD
Kỳ dữ liệu: 2025
Ngày công bố: 2025-04-01T00:00:00
Tổ chức công bố: OECD
Phương pháp/ghi chú: Các tỷ lệ trong biểu đồ là trung bình mẫu khảo sát và không đại diện cho toàn bộ SME thế giới hay Việt Nam; nếu chatbot nêu con số cần trích đúng biểu đồ/trang PDF.
URL nguồn: https://www.oecd.org/content/dam/oecd/en/publications/reports/2025/04/sme-digitalisation-for-competitiveness_3116862a/197e3077-en.pdf
