insert into public.pm_knowledge(external_id,title,content,kind,review_status,source_sheet,published,url,source_references,metadata) values ('MKT008','Khung quản trị rủi ro AI · Quản trị AI','Chủ đề: Quản trị AI
Chỉ tiêu/nội dung: Khung quản trị rủi ro AI
Giá trị/tóm tắt: NIST AI RMF cung cấp khung tự nguyện hỗ trợ tổ chức quản lý rủi ro AI; các đặc tính đáng tin cậy gồm hợp lệ/đáng tin cậy, an toàn, bảo mật, có khả năng chống chịu, minh bạch, giải thích được, bảo vệ riêng tư và quản lý thiên lệch có hại.
Đơn vị: Khung hướng dẫn
Phạm vi địa lý: Hoa Kỳ/áp dụng tham khảo quốc tế
Kỳ dữ liệu: AI RMF 1.0
Ngày công bố: 2023-01-01T00:00:00
Tổ chức công bố: NIST
Phương pháp/ghi chú: Không phải luật bắt buộc áp dụng cho mọi doanh nghiệp Việt Nam; dùng như tài liệu tham khảo quản trị.
URL nguồn: https://www.nist.gov/itl/ai-risk-management-framework/ai-risk-management-framework-faqs
