insert into public.pm_reference(external_id,category,data,approved) values ('CS007','handoff','{"fields": {"CASE_ID": "CS007", "Tình huống": "Đánh giá nhà cung cấp/đề nghị chứng thực", "Dấu hiệu": "Yêu cầu xác nhận uy tín, chứng chỉ, chất lượng hoặc khiếu nại nhà cung cấp", "Thông tin cần hỏi": "Tên pháp nhân; mã số thuế; bằng chứng công khai; nội dung cần xác minh", "Bộ phận nhận": "Quản lý nhà cung cấp", "Ưu tiên": "Cao", "SLA phản hồi": "Trong 1 ngày làm việc – đề xuất, cần phê duyệt", "Thông báo người dùng": "POLYMATCH cần kiểm tra hồ sơ và bằng chứng trước khi đưa ra kết luận.", "Điều kiện chuyển": "Yêu cầu chứng thực hoặc có dấu hiệu thông tin nhà cung cấp không chính xác.", "Người duyệt": "Quản lý đối tác"}, "origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Chuyen_tiep_CSKH", "row": 10}}'::jsonb,false) on conflict(external_id) do nothing;
insert into public.pm_reference(external_id,category,data,approved) values ('CS008','handoff','{"fields": {"CASE_ID": "CS008", "Tình huống": "Yêu cầu gặp nhân viên", "Dấu hiệu": "Người dùng nói muốn gặp người thật hoặc không hài lòng với chatbot", "Thông tin cần hỏi": "Chủ đề; khung giờ liên hệ; phương thức liên hệ mà người dùng đồng ý cung cấp", "Bộ phận nhận": "CSKH", "Ưu tiên": "Bình thường", "SLA phản hồi": "Trong 1 ngày làm việc – đề xuất, cần phê duyệt", "Thông báo người dùng": "Tôi có thể chuyển yêu cầu để nhân viên liên hệ. Bạn chỉ cần cung cấp thông tin liên hệ nếu đồng ý.", "Điều kiện chuyển": "Người dùng yêu cầu nhân viên hoặc từ chối tiếp tục với chatbot.", "Người duyệt": "Nhóm CSKH"}, "origin": {"file": "Mau_data_chatbot_POLYMATCH.xlsx", "sha256": "060c75f9a4f5b7480d3c48eb1926b05bcb43430dae93744007f423b22cc311f2", "sheet": "Chuyen_tiep_CSKH", "row": 11}}'::jsonb,false) on conflict(external_id) do nothing;
